/* core/blenderexport.js -- GENERATED by src/core_blenderexport.py. Do not edit by hand.

   Søren, 2026-09-06: "There should be an option to select download Blender file and then you
   download this code." So the bounding-box panel's button writes THIS notebook instead of the
   EM/segmentation one when "Blender file" is ticked.

   ── WHY THIS FILE IS GENERATED ──────────────────────────────────────────────────────────────

   It carries blender/ujump_blender_scene.ipynb verbatim, as data, and replaces exactly one cell
   -- the one tagged "params" -- with the panel's own values. Every other cell reaches Colab
   byte-identical to the notebook this repository tests with emplancheck (15), emfetchcheck (23),
   notebookcheck (14) and blendscenecheck (18).

   The alternative was a hand-written JavaScript twin of make_colab_notebook.py. That would be a
   second definition of the same pipeline, and the two would drift -- silently, because only one
   of them would have checks. Re-run the generator after editing any of blend_scene.py,
   glb_write.py, em_plan.py, em_fetch.py or make_colab_notebook.py.

   ── WHAT THE NOTEBOOK DOES, IN ONE PARAGRAPH ────────────────────────────────────────────────

   Fetches the matched cells' meshes and their nuclei, plans an EM (and segmentation) cutout for
   the box against the source's own scale ladder and REFUSES a box no available level can bring
   under the caps, writes the sections as PNGs with the matched cells painted over them, writes a
   .glb in pure Python, then -- best effort -- downloads Blender and builds a .blend with a
   three-act animation: the sections run out with no models drawn, back with them in place, then
   the camera pulls back and turns. Ctrl+F12 renders an MP4.

   Public surface: UJ.blender.buildNotebook(opts), UJ.blender.downloadNotebook(opts).
*/
window.UJ = window.UJ || {};
UJ.blender = (function(){
  "use strict";

  /* The tested notebook, whole. */
  const NB_SOURCE = "{\"nbformat\": 4, \"nbformat_minor\": 0, \"metadata\": {\"colab\": {\"provenance\": [], \"toc_visible\": true}, \"kernelspec\": {\"name\": \"python3\", \"display_name\": \"Python 3\"}, \"language_info\": {\"name\": \"python\"}}, \"cells\": [{\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"# \u00b5Jump \u2192 3D: matched cells, with their nuclei inside\\n\\nA **test**, not the finished feature. It takes a list of matched cells, fetches each one's\\nfull mesh and its nucleus mesh, and writes two files you download:\\n\\n| file | needs | what it is |\\n|---|---|---|\\n| `microns_cells.glb` | nothing | the geometry. Opens in Blender 2.80 onward, Maya, Cinema4D, Houdini, Sketchfab, PowerPoint, any web viewer. |\\n| `microns_cells_blender.zip` | Blender download | the full scene \u2014 collections per cell type, micrometre units, camera, the three-act animation \u2014 plus the EM sections it needs. |\\n\\n### What the box includes decides what you get\\n\\nThe bounding box has four independent switches, and every combination is a sensible scene:\\n\\n| included | the animation |\\n|---|---|\\n| EM + 3D models | sweep out with no models, sweep back with them, pull back, then turn |\\n| 3D models only | turn |\\n| EM only, or segmentation only | sweep out and back, and stop \u2014 there is nothing to rotate around |\\n| segmentation | doesn't change the shape of the animation; the matched cells are painted over the sections |\\n\\n**Nuclei decide the transparency.** Included, the cells are translucent so a nucleus stays\\nvisible through its own cell the way it does in Neuroglancer; not included, the cells are solid,\\nbecause the transparency then costs contrast and shows nothing.\\n\\nThe full animation is three acts and a hinge:\\n\\n1. **the sections run out**, back to front, face-on and filling the frame, with no 3D models\\n   drawn at all \u2014 the tissue and its segmentation on their own, which is the honest order for\\n   a figure that is arguing *from* the imagery;\\n2. **the sections run back**, front to back, with the models present throughout \u2014 the plane\\n   retreating past them uncovers them;\\n3. a one-second **pull-back** to whatever framing holds the whole cell set, then **the\\n   turntable**: 240 frames, one revolution, 10 s at 24 fps, looping seamlessly.\\n\\nCtrl+F12 renders an MP4 PowerPoint plays.\\n\\n**The `.glb` is written first and in pure Python**, so a failure downloading Blender costs you\\nthe scene but never the cells. Version 1 had it the other way round, and a 403 from\\n`download.blender.org` meant coming away with nothing after paying for every fetch.\\n\\n### What this run is meant to answer\\n\\n1. **How big is a cell 3D model, really?** Vertices and megabytes per cell at each level of\\n   detail tried. That number decides how many cells the tool can offer before it has to refuse\\n   \u2014 the one thing that cannot be measured from the browser side.\\n2. **How large an EM box is affordable?** Section 6 prints the mip, pixel size, section count\\n   and megabytes *before* fetching anything, and refuses a box that no available level can\\n   bring under the caps. The caps are guesses until a real run either sails through them or\\n   crawls.\\n3. **Does the scene open correctly?** Micrometre units, sane clipping, nucleus visible through\\n   the cell, one collection per cell type, and the EM landing on the cells rather than beside\\n   them.\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 1. What to include, and which cells\\n\\nFive real cells, one per type, read out of the live \u00b5Jump page. When this becomes a button,\\n\u00b5Jump fills this list in from Filter and show \u2014 the way `core/colabexport.js` already writes\\n`MESH_ROOT_IDS` into the EM/segmentation notebook \u2014 and `INCLUDE` comes from the checkboxes on\\nthe bounding-box panel.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {\"ujump\": \"params\"}, \"outputs\": [], \"source\": \"# These four are the bounding-box panel's checkboxes. ALL ON by default: the first run of\\n# this notebook had segmentation off, and a run that quietly produces plain grey sections\\n# because a switch defaulted the other way costs an hour and teaches nothing.\\nINCLUDE = {\\n    'em':            True,    # the imagery\\n    'segmentation':  True,    # the matched cells painted over it\\n    'cell_3d_model': True,    # the full cell meshes\\n    'nuclei':        True,    # the nucleus meshes \u2014 and what makes the cells translucent\\n    'vasculature':   True,    # Wan & Wei's TriSAM blood vessels, cut to the same box\\n}\\n\\nCELLS = [\\n    {\\n        \\\"type\\\": \\\"23P\\\",\\n        \\\"root_id\\\": \\\"864691135275621605\\\",\\n        \\\"nucleus_id\\\": \\\"190151\\\"\\n    },\\n    {\\n        \\\"type\\\": \\\"BC\\\",\\n        \\\"root_id\\\": \\\"864691135948379684\\\",\\n        \\\"nucleus_id\\\": \\\"369908\\\"\\n    },\\n    {\\n        \\\"type\\\": \\\"astrocyte\\\",\\n        \\\"root_id\\\": \\\"864691136380797141\\\",\\n        \\\"nucleus_id\\\": \\\"204873\\\"\\n    },\\n    {\\n        \\\"type\\\": \\\"oligo\\\",\\n        \\\"root_id\\\": \\\"864691135194387242\\\",\\n        \\\"nucleus_id\\\": \\\"408486\\\"\\n    },\\n    {\\n        \\\"type\\\": \\\"microglia\\\",\\n        \\\"root_id\\\": \\\"864691135583699064\\\",\\n        \\\"nucleus_id\\\": \\\"609796\\\"\\n    }\\n]\\n\\n# core/charts.js PALETTE \u2014 the same colours \u00b5Jump's own charts use.\\nPALETTE = [\\\"#8a3b2a\\\", \\\"#5a4a7a\\\", \\\"#3a6b5a\\\", \\\"#a37a3a\\\", \\\"#4a6b8a\\\", \\\"#7a3a5a\\\", \\\"#6b7a3a\\\", \\\"#3a5a6b\\\"]\\nCOLORS = {c['type']: PALETTE[i % len(PALETTE)] for i, c in enumerate(CELLS)}\\n\\nEM  = 'gs://iarpa_microns/minnie/minnie65/em'          # UJ.cfg.em.emSource\\nSEG = 'precomputed://https://storage.googleapis.com/iarpa_microns/minnie/minnie65/seg_m1300'\\nNUC = 'precomputed://https://bossdb-open-data.s3.amazonaws.com/iarpa_microns/minnie/minnie65/nuclei'\\n# Wan & Wei's TriSAM segmentation of the blood vessels in the whole minnie65 volume, on\\n# BossDB -- https://doi.org/10.1109/JBHI.2025.3576643 (open access), data at\\n# bossdb.org/project/wei2024. The same asset uJump's 'Include vasculature segmentation'\\n# checkbox puts in the Neuroglancer view, and a DIFFERENT thing from the 'vasculature\\n# outline' checkbox, which shows the single merged blob left inside MICrONS's own cell\\n# segmentation.\\nVASC = 'precomputed://https://bossdb-open-data.s3.amazonaws.com/wei2024/minnie/bv'\\n# None means 'any non-zero label is vessel', which is right for a dedicated vessel\\n# segmentation. Set [1] to take only the segment uJump's viewer selects.\\nVASC_IDS   = None\\nVASC_COLOR = '#b03a48'\\nVASC_ALPHA = 0.30        # always translucent: a vessel through a 60 um box is a wall\\n\\n# FINEST FIRST, and that is a correction. This read [3, 2, 1, 0] -- coarsest first -- with a\\n# rule of 'keep the first level that stays under the vertex budget'. Level 3 is the coarsest\\n# and therefore always under any budget, so the loop stopped there every single time and the\\n# budget never did anything: every cell came out at the lowest resolution the dataset has,\\n# which is the faceted look the models had. Now the walk starts at level 0 and the budget is\\n# what stops it.\\nLOD_PREFERENCE = [0, 1, 2, 3]\\n# Per cell, and shared. A microglia at level 0 is a few hundred thousand vertices and worth\\n# having; a pyramidal neuron can be several million, and twenty of those is a download nobody\\n# wants. The per-cell cap is whichever is smaller: VERTEX_BUDGET, or the total split evenly.\\nVERTEX_BUDGET       = 2_000_000   # per cell\\nVERTEX_BUDGET_TOTAL = 8_000_000   # across the whole export\\n\\n\\n# \u2500\u2500 the box, and what it is allowed to cost \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n# Raise the caps if a run has bandwidth to spare; the planner obeys whatever it is given\\n# and never picks a level that breaks them.\\nEM_MAX_PX       = 1024    # longest in-plane side of a written section\\nEM_MAX_SECTIONS = 120     # frames in each sweep \u2014 5 s at 24 fps\\nEM_MAX_MB       = 400     # over the wire, uncompressed uint8\\nOVERLAY_OPACITY = 0.35    # core/colabexport.js uses the same figure\\n# The vasculature gets its own caps: it is surfaced, not drawn, so what matters is the\\n# triangle count rather than the picture size, and it is a 3D block rather than a stack of\\n# sections. VASC_STEP is decimation on the marching-cubes grid -- 2 quarters the triangles.\\nVASC_MAX_PX       = 512\\nVASC_MAX_SECTIONS = 512\\nVASC_MAX_MB       = 250\\nVASC_STEP         = 1\\n\\nEM_BOX_MODE    = 'around_first_cell'   # or 'all_cells', or 'manual'\\nEM_BOX_SIZE_UM = (60.0, 60.0, 30.0)    # used by 'around_first_cell'\\nEM_BOX_UM      = None                  # used by 'manual': ((x0,y0,z0),(x1,y1,z1)) dataset um\\n\\non = [k for k, v in INCLUDE.items() if v]\\nprint(f'{len(CELLS)} cells: ' + ', '.join(c['type'] for c in CELLS))\\nprint('including: ' + (', '.join(on) if on else 'NOTHING \u2014 switch something on'))\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 2. Install\\n\\n`cloud-volume` only \u2014 Blender comes later, and only if it can. Pip will warn that `dill` and\\n`multiprocess` now conflict with Colab's preinstalled `datasets`; that is harmless here,\\nnothing in this notebook uses it.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"%pip install -q cloud-volume\\n\\nimport os, sys, json, time, re, glob, subprocess, urllib.request\\nimport numpy as np\\n\\nos.makedirs('/content/out/meshes', exist_ok=True)\\nprint('python', sys.version.split()[0])\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 3. The four modules\\n\\nAll verbatim from the tool's repository \u2014 the same files that will run when this becomes a\\nbutton. None of them knows anything about CAVE, so all three are testable without touching the\\nnetwork, and all three were tested that way before this notebook existed.\\n\\n| module | needs | checked by |\\n|---|---|---|\\n| `glb_write.py` | numpy | `glbwritecheck.py` \u2014 15 checks, decodes its own output back |\\n| `blend_scene.py` | Blender | rendered frames, not assertions: the orientation and the sweep are pictures |\\n| `em_plan.py` | nothing | `emplancheck.py` \u2014 15 checks against the real minnie65 scale list |\\n| `em_fetch.py` | numpy, Pillow | `emfetchcheck.py` \u2014 23 checks on stub volumes, every EM/segmentation combination |\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"%%writefile /content/glb_write.py\\n\\\"\\\"\\\"Write a multi-cell .glb from numpy arrays, with no Blender involved.           2026-09-06\\n\\nS\u00f8ren's first Colab run got as far as fetching Blender and stopped:\\n\\n    HTTPError: HTTP Error 403: Forbidden      (download.blender.org)\\n\\nThat is worth fixing, but it also exposed a design fault worth fixing first: in the original\\nnotebook, Blender produced BOTH outputs, so failing to download Blender meant coming away with\\nnothing at all -- no scene and no geometry, after paying for every mesh fetch.\\n\\nSo the .glb is written here instead, in pure Python. It needs numpy and nothing else, it cannot\\n403, and it is the artefact that matters most for \\\"it is for everyone and not just me\\\": glTF\\nimports into Blender 2.80 onward and into Maya, Cinema4D, Houdini, Sketchfab, PowerPoint and every\\nweb viewer. The .blend is now the bonus that needs Blender, rather than the other way round.\\n\\n\u2500\u2500 THE FRAME \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nglTF is Y-up; MICrONS and every other Neuroglancer precomputed source is Y-DOWN. The conversion\\nis the same one core/mesh.js already applies to \u00b5Jump's per-cell \\\"3D model\\\" download:\\n\\n    dataset (x, y, z) -> glTF (x, -y, z), with face winding swapped\\n\\nso a .glb written here and a .glb downloaded from \u00b5Jump's own button open in the same\\norientation. That is not a coincidence to preserve by luck -- glbframecheck asserts it.\\n\\n\u2500\u2500 WHAT IT WRITES, AND WHAT IT LEAVES OUT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nOne node and one mesh per object, named for the cell; one material per object with\\n`baseColorFactor` and `alphaMode` BLEND (cells) or OPAQUE (nuclei), which is what makes a nucleus\\nvisible through its own cell in viewers that honour it.\\n\\nNo collections, no unit scale, no camera, no viewport clipping -- glTF has nowhere to put them.\\nThose live in the .blend. Do not add them here by inventing extras nobody reads.\\n\\nPositions are float32 and indices uint32, in one buffer, 4-byte aligned as the spec requires.\\nEvery accessor carries min/max on POSITION, which the spec makes mandatory and which several\\nimporters genuinely use for framing.\\n\\\"\\\"\\\"\\nimport json\\nimport struct\\n\\nimport numpy as np\\n\\nGLTF_MAGIC = 0x46546C67\\nJSON_CHUNK = 0x4E4F534A\\nBIN_CHUNK = 0x004E4942\\n\\nFLOAT = 5126\\nUINT = 5125\\n\\n\\ndef to_gltf_frame(verts, faces):\\n    \\\"\\\"\\\"dataset (x, y, z) -> glTF (x, -y, z). Negating one axis mirrors, so winding is swapped\\n    to keep normals facing out; see core/mesh.js flipYForGLTF, which this mirrors exactly.\\\"\\\"\\\"\\n    v = np.asarray(verts, dtype=np.float32).copy()\\n    v[:, 1] = -v[:, 1]\\n    return v, np.asarray(faces, dtype=np.uint32)[:, [0, 2, 1]]\\n\\n\\ndef _pad4(b, fill=b\\\"\\\\x00\\\"):\\n    return b + fill * ((4 - (len(b) % 4)) % 4)\\n\\n\\ndef write_glb(path, objects, generator=\\\"uJump Blender export\\\"):\\n    \\\"\\\"\\\"objects: [{name, verts (N,3) \u00b5m dataset frame, faces (M,3), color '#rrggbb', alpha}]\\n\\n    Returns a small summary dict rather than nothing, so a caller can report and a check can\\n    assert without reopening the file.\\n    \\\"\\\"\\\"\\n    buf = bytearray()\\n    accessors, views, meshes, nodes, materials = [], [], [], [], []\\n\\n    def add_view(data, target):\\n        nonlocal buf\\n        while len(buf) % 4:\\n            buf.append(0)\\n        off = len(buf)\\n        buf.extend(data)\\n        views.append({\\\"buffer\\\": 0, \\\"byteOffset\\\": off, \\\"byteLength\\\": len(data), \\\"target\\\": target})\\n        return len(views) - 1\\n\\n    n_tris = 0\\n    for ob in objects:\\n        v, f = to_gltf_frame(ob[\\\"verts\\\"], ob[\\\"faces\\\"])\\n        if not len(v) or not len(f):\\n            continue\\n        n_tris += len(f)\\n\\n        idx_view = add_view(f.reshape(-1).astype(\\\"<u4\\\").tobytes(), 34963)\\n        pos_view = add_view(v.reshape(-1).astype(\\\"<f4\\\").tobytes(), 34962)\\n\\n        accessors.append({\\\"bufferView\\\": idx_view, \\\"componentType\\\": UINT,\\n                          \\\"count\\\": int(f.size), \\\"type\\\": \\\"SCALAR\\\"})\\n        accessors.append({\\\"bufferView\\\": pos_view, \\\"componentType\\\": FLOAT,\\n                          \\\"count\\\": int(len(v)), \\\"type\\\": \\\"VEC3\\\",\\n                          # Mandatory on POSITION, and several importers frame the view with it.\\n                          \\\"min\\\": [float(x) for x in v.min(axis=0)],\\n                          \\\"max\\\": [float(x) for x in v.max(axis=0)]})\\n        a_idx, a_pos = len(accessors) - 2, len(accessors) - 1\\n\\n        h = (ob.get(\\\"color\\\") or \\\"#888888\\\").lstrip(\\\"#\\\")\\n        if len(h) == 3:\\n            h = \\\"\\\".join(c * 2 for c in h)\\n        rgb = [int(h[i:i + 2], 16) / 255.0 for i in (0, 2, 4)]\\n        alpha = float(ob.get(\\\"alpha\\\", 1.0))\\n        materials.append({\\n            \\\"name\\\": \\\"mat_\\\" + ob[\\\"name\\\"],\\n            \\\"pbrMetallicRoughness\\\": {\\\"baseColorFactor\\\": rgb + [alpha],\\n                                     \\\"metallicFactor\\\": 0.0, \\\"roughnessFactor\\\": 0.55},\\n            # BLEND is what makes the cell see-through in a viewer; nuclei stay OPAQUE.\\n            \\\"alphaMode\\\": \\\"BLEND\\\" if alpha < 1.0 else \\\"OPAQUE\\\",\\n            \\\"doubleSided\\\": True,\\n        })\\n        meshes.append({\\\"name\\\": ob[\\\"name\\\"],\\n                       \\\"primitives\\\": [{\\\"attributes\\\": {\\\"POSITION\\\": a_pos}, \\\"indices\\\": a_idx,\\n                                       \\\"mode\\\": 4, \\\"material\\\": len(materials) - 1}]})\\n        nodes.append({\\\"mesh\\\": len(meshes) - 1, \\\"name\\\": ob[\\\"name\\\"]})\\n\\n    if not nodes:\\n        raise ValueError(\\\"nothing to write: every object had no vertices or no faces\\\")\\n\\n    gltf = {\\n        \\\"asset\\\": {\\\"version\\\": \\\"2.0\\\", \\\"generator\\\": generator},\\n        \\\"scene\\\": 0, \\\"scenes\\\": [{\\\"nodes\\\": list(range(len(nodes)))}],\\n        \\\"nodes\\\": nodes, \\\"meshes\\\": meshes, \\\"materials\\\": materials,\\n        \\\"accessors\\\": accessors, \\\"bufferViews\\\": views,\\n        \\\"buffers\\\": [{\\\"byteLength\\\": len(buf)}],\\n    }\\n\\n    js = _pad4(json.dumps(gltf, separators=(\\\",\\\", \\\":\\\")).encode(\\\"utf-8\\\"), b\\\" \\\")\\n    bn = _pad4(bytes(buf))\\n    total = 12 + 8 + len(js) + 8 + len(bn)\\n    out = bytearray()\\n    out += struct.pack(\\\"<III\\\", GLTF_MAGIC, 2, total)\\n    out += struct.pack(\\\"<II\\\", len(js), JSON_CHUNK) + js\\n    out += struct.pack(\\\"<II\\\", len(bn), BIN_CHUNK) + bn\\n    with open(path, \\\"wb\\\") as fh:\\n        fh.write(out)\\n\\n    return {\\\"path\\\": path, \\\"bytes\\\": total, \\\"objects\\\": len(nodes), \\\"triangles\\\": n_tris,\\n            \\\"translucent\\\": sum(1 for m in materials if m[\\\"alphaMode\\\"] == \\\"BLEND\\\")}\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"%%writefile /content/blend_scene.py\\n\\\"\\\"\\\"Build a Blender scene from a Filter-and-show result.                            2026-09-06\\n\\n    blender --background --python blend_scene.py -- manifest.json out.blend [preview.png]\\n\\nRuns inside Blender's own Python (any version from 4.2 to 5.x), so it needs nothing installed.\\nEverything it draws comes from a manifest written by whatever fetched the meshes -- the Colab\\nnotebook today, \u00b5Jump itself later -- which means this file never talks to CAVE, cloud-volume or\\na browser, and can be tested on synthetic geometry.\\n\\nS\u00f8ren, 2026-09-06: \\\"full meshes for the matched cells, but the nuclei should also be included and\\nbe visible through the cell meshes, like in the Neuroglancer instances.\\\"\\n\\n\u2500\u2500 THE MANIFEST \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\n{\\n  \\\"dataset\\\":  \\\"MICrONS minnie65\\\",           # free text, ends up in the scene name\\n  \\\"source\\\":   \\\"\u00b5Jump Filter and show\\\",      # free text\\n  \\\"units\\\":    \\\"um\\\",                         # only \\\"um\\\" is accepted; see UNITS below\\n  \\\"frame\\\":    \\\"microns\\\",                    # \\\"microns\\\" (Y down, as every Neuroglancer\\n                                            #  precomputed source is) or \\\"blender\\\"\\n  \\\"colors\\\":   {\\\"Astrocyte\\\": \\\"#8a3b2a\\\", ...},# per cell type, the tool's own palette\\n  \\\"cells\\\": [\\n    {\\\"name\\\": \\\"Astrocyte_864691135...\\\", \\\"type\\\": \\\"Astrocyte\\\",\\n     \\\"root_id\\\": \\\"864691135...\\\", \\\"nucleus_id\\\": \\\"294657\\\",\\n     \\\"cell_npz\\\": \\\"meshes/cell_864691135....npz\\\",      # optional\\n     \\\"nucleus_npz\\\": \\\"meshes/nuc_294657.npz\\\",          # optional\\n     \\\"position_um\\\": [712.4, 533.1, 899.0]}            # nucleus centroid, for the report\\n  ]\\n}\\n\\nEach .npz holds `verts` (N x 3 float32, ABSOLUTE micrometres) and `faces` (M x 3 int32). Raw\\narrays rather than .ply or .obj on purpose: Blender's import operators have been renamed twice\\nsince 3.x (`import_mesh.ply` -> `wm.ply_import`), and numpy is bundled with Blender, so\\nfrom_pydata/foreach_set works identically on every version this has to run on.\\n\\n\u2500\u2500 WHAT IT BUILDS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\n  Collection \\\"Cells\\\"      one sub-collection per cell type, each cell a named object\\n  Collection \\\"Nuclei\\\"     the matching nucleus, same name with a Nucleus_ prefix\\n  materials               one translucent per type for the cell, one opaque per type for the\\n                          nucleus -- see TRANSPARENCY below, this is the bit S\u00f8ren asked for\\n  camera + key light      framing the whole set\\n  3D cursor               at the set's centroid, so orbiting works out of the box\\n\\n\u2500\u2500 COORDINATES: ABSOLUTE MICROMETRES, DELIBERATELY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nThe obvious move is to recentre everything on the set's centroid so the scene sits at the origin.\\nThis does NOT do that. A coordinate read off an object in Blender is the same number \u00b5Jump shows\\nand the same number you can paste into Neuroglancer, and that is worth more than tidiness. A\\nMICrONS volume is about 1300 x 870 x 820 \u00b5m, so at 1 unit = 1 \u00b5m the scene sits a few hundred\\nunits from the origin -- far enough to need the camera and clipping set up (below), nowhere near\\nfar enough for float32 precision to matter.\\n\\nThe 3D cursor is parked on the centroid instead, so \\\"orbit around the selection\\\" behaves.\\n\\n\u2500\u2500 UNITS AND CLIPPING, the two things that go wrong \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\n1 Blender unit = 1 \u00b5m, and the scene is told so: unit_settings.scale_length = 1e-6 with\\nlength_unit = 'MICROMETERS'. Blender's UI then reads out in real micrometres.\\n\\nThe trap is the viewport's far clipping plane. Blender's default is 100 m -- i.e. 100 units --\\nand a MICrONS filter result spans several hundred. Without raising clip_end the .blend opens on\\nan apparently EMPTY viewport: the geometry is there, correct, and entirely behind the far plane.\\nEvery VIEW_3D space in the saved file gets clip_end set from the actual bounding box, and\\nclip_start dropped to 0.01 so you can still fly inside a cell.\\n\\n\u2500\u2500 WHICH BLENDER TO BUILD WITH \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nBlender opens files written by OLDER versions and refuses files written by NEWER ones, so this\\nshould always run in the oldest Blender that has to open the result. Getting it wrong does not\\nproduce a warning; it produces \\\"Failed to read blend file ..., not a blend file\\\", which reads\\nexactly like a corrupt download.\\n\\nThat is not a hypothetical: the first test scene delivered here was built with bpy 5.0.1, whose\\nfiles start \\\"BLENDER17-01v0500\\\" -- a header format introduced in 5.0 that no earlier Blender can\\nparse. The file transferred perfectly and was completely unopenable. 4.2 LTS is the safe floor\\ntoday. The version that wrote a file is stamped on the scene as `written_by_blender` and printed\\nin the report.\\n\\nWhich version is \\\"oldest\\\" is a moving target: as of 2026-09 only 4.5 LTS (to July 2027) and 5.2\\nLTS are still supported, and 4.2 LTS went out of support in July 2026. 4.5 is the current sensible\\nfloor -- its files open in 4.5 through 5.2 and later, and anything older is unsupported software.\\n\\nA .glb is written alongside the .blend for exactly this reason. glTF has no version rule: it\\nimports into Blender 2.80 onward and into every other 3D tool. It is written BEFORE the\\ncamera, lights and scale bar exist, so it holds cells and nuclei and no furniture.\\n\\n\u2500\u2500 TRANSPARENCY: THE NUCLEUS SEEN THROUGH THE CELL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nNeuroglancer does this with `objectAlpha` on the segmentation layer -- the cell surface goes\\ntranslucent and anything inside stays visible. The Blender equivalent needs three settings, not\\none, and two of them are the ones people miss:\\n\\n  alpha                     CELL_ALPHA (0.25) on the cell, 1.0 on the nucleus\\n  blend_method / surface_render_method\\n                            'BLEND' (4.x) or 'BLENDED' (EEVEE Next) -- without it EEVEE clips\\n                            alpha to a dither pattern and the nucleus shows through as noise\\n  show_transparent_back     FALSE. This is the one that matters. Left on, you see the INSIDE of\\n                            the cell's own far surface through its near surface, which reads as a\\n                            muddy double layer and hides the nucleus behind it. Off, the cell\\n                            reads as a single clean shell with the nucleus floating inside it,\\n                            which is what Neuroglancer looks like.\\n\\nWhich of blend_method / surface_render_method exists depends on the Blender version, so both are\\nset through a getattr guard rather than assumed -- probed on 5.0.1, where blend_method offers\\nOPAQUE/CLIP/HASHED/BLEND and surface_render_method offers DITHERED/BLENDED.\\n\\nCycles ignores all three and does the right thing from the alpha alone, so a render in either\\nengine shows the nucleus.\\n\\\"\\\"\\\"\\nimport json\\nimport math\\nimport os\\nimport sys\\nimport tempfile\\n\\nimport bpy\\nimport mathutils\\nimport numpy as np\\n\\nUNITS_UM = \\\"um\\\"\\n\\n# How see-through a cell is. 0.18 was the first try and read too faint on a lit background; 0.25\\n# kept the membrane legible on synthetic blobs. On a REAL cell it did not: S\u00f8ren, on an export of\\n# one microglia, \\\"It looks like there is a faint contour of the 3D model now, not totally black,\\n# but it is very weak.\\\"\\n#\\n# The arithmetic says why, and it is not a lighting fault. An alpha-blended surface contributes\\n# `alpha` of its own shaded colour and lets `1 - alpha` of what is behind it through. Behind it is\\n# uJump's #0d1117 -- 0.006 in linear light, i.e. nothing. So at alpha 0.25 the brightest a\\n# membrane can ever be is a QUARTER of its lit colour, over black. A real cell is mostly thin\\n# neurites seen nearly edge-on, where the lit colour is low to begin with, and a quarter of a low\\n# number is the faint contour he photographed.\\n#\\n# Three things were raised together, because no one of them is enough on its own: alpha (here),\\n# the light energies (see build()), and an emission floor in the material (see make_material) so\\n# the colour survives even where no light reaches. 0.35 still shows a nucleus through a soma --\\n# checked on the same six-cell scene -- and is half again as bright as 0.25.\\nCELL_ALPHA = 0.35\\n\\n# Every cell and nucleus emits a little of its own colour, on top of being lit.\\n#\\n# This is the guard that does not depend on where anything is. Three suns can be aimed correctly\\n# and still leave a surface dark -- occluded, facing away, or (on a translucent cell) simply\\n# multiplied down by its own alpha. An emission term is unconditional: the palette colour uJump\\n# shows in its charts is the colour the model reads as, before a single lamp is considered.\\n#\\n# Kept well below 1.0 on purpose. At 1.0 the model is a flat silhouette of its own colour with no\\n# shading at all, which throws away the entire point of the key/fill/rim -- you can no longer see\\n# which way a membrane curves. These are floors, not the light.\\nCELL_EMISSION = 0.55        # translucent membranes, which lose 1 - alpha of everything\\nNUC_EMISSION = 0.22         # opaque, so it needs much less\\n\\n# \u00b5Jump's own dark-theme background (:root{--bg:#0d1117} in ujump.html). Written as the hex the\\n# stylesheet uses rather than as linear floats, so the two can be compared by eye in a diff.\\nUJUMP_BG = \\\"#0d1117\\\"\\n\\n# S\u00f8ren: \\\"240 frames, so that if I make a video in 10s and 24 frames per second it does a full\\n# round.\\\" 240 / 24 = 10 s exactly, and both numbers are his rather than a default worth changing\\n# quietly -- a turntable whose period is not a round number of seconds is a nuisance to cut against.\\n# Named TURNTABLE_FRAMES rather than FRAMES because this file already had a FRAMES -- the\\n# COORD_FRAMES table of coordinate conventions, 270 lines down. The first version of this constant\\n# shadowed it and the build died with \\\"unsupported operand type(s) for +: 'dict' and 'int'\\\", which\\n# names neither of the two things involved.\\nTURNTABLE_FRAMES = 240\\n# The pull-back between the sweep and the turntable. One second: long enough not to read as a cut,\\n# short enough that nobody waits through it.\\nZOOM_FRAMES = 24\\nFPS = 24\\n\\n\\ndef argv_after_dashes():\\n    return sys.argv[sys.argv.index(\\\"--\\\") + 1:] if \\\"--\\\" in sys.argv else []\\n\\n\\n# \u2500\u2500 colour \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\ndef srgb_to_linear(c):\\n    \\\"\\\"\\\"Blender node colours are LINEAR. Feeding sRGB hex straight in makes every material read\\n    washed out and lighter than the palette it came from -- the tool's #8a3b2a arrives looking\\n    like a pale brick. This is the standard sRGB EOTF, not a gamma 2.2 approximation.\\\"\\\"\\\"\\n    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4\\n\\n\\ndef hex_rgba(h, alpha=1.0):\\n    h = (h or \\\"#888888\\\").lstrip(\\\"#\\\")\\n    if len(h) == 3:\\n        h = \\\"\\\".join(ch * 2 for ch in h)\\n    rgb = [srgb_to_linear(int(h[i:i + 2], 16) / 255.0) for i in (0, 2, 4)]\\n    return (rgb[0], rgb[1], rgb[2], alpha)\\n\\n\\ndef principled(mat):\\n    \\\"\\\"\\\"The Principled BSDF of a node material, whatever Blender calls its sockets this year.\\\"\\\"\\\"\\n    for n in mat.node_tree.nodes:\\n        if n.type == \\\"BSDF_PRINCIPLED\\\":\\n            return n\\n    return None\\n\\n\\ndef set_socket(node, names, value):\\n    for n in names:\\n        if n in node.inputs:\\n            node.inputs[n].default_value = value\\n            return True\\n    return False\\n\\n\\ndef make_material(name, hex_colour, alpha, translucent):\\n    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name)\\n    mat.use_nodes = True\\n    bsdf = principled(mat)\\n    if bsdf:\\n        set_socket(bsdf, [\\\"Base Color\\\"], hex_rgba(hex_colour, 1.0))\\n        set_socket(bsdf, [\\\"Alpha\\\"], alpha)\\n        set_socket(bsdf, [\\\"Roughness\\\"], 0.55 if translucent else 0.35)\\n        # Some sheen keeps a translucent membrane readable at grazing angles instead of\\n        # disappearing where it is most nearly edge-on -- which is exactly where a neurite is.\\n        set_socket(bsdf, [\\\"Specular IOR Level\\\", \\\"Specular\\\"], 0.25 if translucent else 0.4)\\n        # THE EMISSION FLOOR. See CELL_EMISSION at the top of the file: this is what stops a\\n        # model reading as a black or near-black silhouette when the lights do not reach it.\\n        #\\n        # The socket names moved in 4.x -- \\\"Emission\\\" became \\\"Emission Color\\\", and a separate\\n        # \\\"Emission Strength\\\" appeared -- so both spellings are offered and set_socket takes\\n        # whichever exists. Getting this wrong is silent: the value goes nowhere and the model is\\n        # dark again, which is the failure this is here to prevent, so the return value is\\n        # checked and a missing socket is reported rather than shrugged off.\\n        strength = CELL_EMISSION if translucent else NUC_EMISSION\\n        got_col = set_socket(bsdf, [\\\"Emission Color\\\", \\\"Emission\\\"], hex_rgba(hex_colour, 1.0))\\n        got_str = set_socket(bsdf, [\\\"Emission Strength\\\"], strength)\\n        if not (got_col and got_str):\\n            print(\\\"  ! this Blender's Principled BSDF has no %s socket -- '%s' will only be as \\\"\\n                  \\\"bright as the lamps make it\\\"\\n                  % (\\\"emission colour\\\" if not got_col else \\\"emission strength\\\", name))\\n    mat.diffuse_color = hex_rgba(hex_colour, alpha)          # solid/material viewport shading\\n    if translucent:\\n        # See TRANSPARENCY in the module docstring. All three, guarded: which of these exist\\n        # depends on the Blender version and EEVEE generation.\\n        if hasattr(mat, \\\"blend_method\\\"):\\n            mat.blend_method = \\\"BLEND\\\"\\n        if hasattr(mat, \\\"surface_render_method\\\"):\\n            mat.surface_render_method = \\\"BLENDED\\\"\\n        if hasattr(mat, \\\"show_transparent_back\\\"):\\n            mat.show_transparent_back = False\\n        if hasattr(mat, \\\"use_backface_culling\\\"):\\n            mat.use_backface_culling = False\\n        if hasattr(mat, \\\"use_transparent_shadow\\\"):\\n            mat.use_transparent_shadow = True\\n    return mat\\n\\n\\n# \u2500\u2500 geometry \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\ndef add_mesh(name, verts, faces, material, collection):\\n    \\\"\\\"\\\"verts (N,3) float32 in absolute \u00b5m; faces (M,3) int32. Built with foreach_set rather than\\n    from_pydata: on a 400k-vertex astrocyte the difference is seconds against minutes.\\\"\\\"\\\"\\n    me = bpy.data.meshes.new(name)\\n    me.vertices.add(len(verts))\\n    me.vertices.foreach_set(\\\"co\\\", verts.reshape(-1))\\n    me.loops.add(faces.size)\\n    me.loops.foreach_set(\\\"vertex_index\\\", faces.reshape(-1))\\n    me.polygons.add(len(faces))\\n    me.polygons.foreach_set(\\\"loop_start\\\", np.arange(0, faces.size, 3, dtype=np.int32))\\n    me.polygons.foreach_set(\\\"loop_total\\\", np.full(len(faces), 3, dtype=np.int32))\\n    me.update()\\n    me.validate()\\n    # Smooth shading: these are marching-cubes surfaces off a voxel grid, so flat shading shows\\n    # every staircase artefact of the segmentation rather than the cell.\\n    me.polygons.foreach_set(\\\"use_smooth\\\", np.ones(len(me.polygons), dtype=bool))\\n    me.materials.append(material)\\n    ob = bpy.data.objects.new(name, me)\\n    collection.objects.link(ob)\\n    return ob\\n\\n\\n# \u2500\u2500 the turntable, and the scale bar that rides with it \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n# S\u00f8ren, 2026-09-06: \\\"if I press play it rotates around the scene ... 240 frames, so that if I make\\n# a video in 10s and 24 frames per second it does a full round ... a scalebar that rotates with the\\n# camera, so that it always looks the same ... readable text indicating its size above the\\n# scalebar, also rotating with the camera.\\\"\\n#\\n# THE CAMERA BECOMES ORTHOGRAPHIC, and that is the one judgement call in here. A scale bar under a\\n# perspective camera is only true at one depth: a cell nearer the lens than the bar reads bigger\\n# than the bar says, one behind it reads smaller, and the error grows with the spread of the\\n# result. Orthographic projection has no such depth term, so the bar is exact everywhere in frame\\n# -- which is the entire reason for putting one in. It also matches what \u00b5Jump already shows:\\n# every Neuroglancer state this family builds sets orthographicProjection: true.\\n#\\n# Switch back with cam.data.type = \\\"PERSP\\\" if the flatter look is not wanted; the bar then means\\n# \\\"at the middle of the scene\\\" and the label should say so.\\n\\ndef nice_scale_bar_length(view_width):\\n    \\\"\\\"\\\"A 1-2-5 round number near a fifth of the frame. Same rule as core/mesh.js's own\\n    niceScaleBarLength (nearest on a LOG scale, so 1-vs-2 and 50-vs-100 are weighed alike), so a\\n    bar here and a bar in the PowerPoint export pick numbers from the same ladder.\\\"\\\"\\\"\\n    target = max(view_width * 0.20, 1e-6)\\n    exp = math.floor(math.log10(target))\\n    best, best_diff = 1.0, float(\\\"inf\\\")\\n    for e in range(exp - 1, exp + 2):\\n        for b in (1, 2, 5):\\n            v = b * (10.0 ** e)\\n            diff = abs(math.log(v) - math.log(target))\\n            if diff < best_diff:\\n                best, best_diff = v, diff\\n    return best\\n\\n\\ndef emission_material(name, rgb, strength=1.0):\\n    \\\"\\\"\\\"A pure Emission shader, wired by hand rather than through Principled's emission sockets.\\n\\n    The overlay must read the same on a bright cell and on empty space, so it cannot be lit. Doing\\n    it with an explicit Emission node avoids guessing what Principled calls its emission inputs in\\n    a given Blender version (\\\"Emission\\\" became \\\"Emission Color\\\" in 4.x), which is the sort of thing\\n    that silently produces a black scale bar.\\\"\\\"\\\"\\n    mat = bpy.data.materials.new(name)\\n    mat.use_nodes = True\\n    nt = mat.node_tree\\n    nt.nodes.clear()\\n    out = nt.nodes.new(\\\"ShaderNodeOutputMaterial\\\")\\n    em = nt.nodes.new(\\\"ShaderNodeEmission\\\")\\n    em.inputs[0].default_value = (rgb[0], rgb[1], rgb[2], 1.0)\\n    em.inputs[1].default_value = strength\\n    nt.links.new(em.outputs[0], out.inputs[0])\\n    mat.diffuse_color = (rgb[0], rgb[1], rgb[2], 1.0)\\n    return mat\\n\\n\\ndef add_scale_bar(scene, cam, view_w, view_h, label_colour=(0.92, 0.94, 0.97), suffix=\\\"\\\"):\\n    \\\"\\\"\\\"A bar and its label, PARENTED TO THE CAMERA -- which is what makes them \\\"always look the\\n    same\\\" without any per-frame scripting: they are rigidly attached, so they cannot swing, shear\\n    or turn edge-on however the turntable moves.\\n\\n    Both sit just in front of the near clip plane, so nothing in the scene can occlude them, and\\n    both are emissive, so no light rig can dim them. Under an orthographic camera their on-screen\\n    size depends only on ortho_scale, never on that distance -- so placing them close to the lens\\n    costs nothing and buys the overlay behaviour.\\\"\\\"\\\"\\n    length = nice_scale_bar_length(view_w)\\n    z = -(cam.data.clip_start * 4.0 + 1e-3)          # just past the near plane\\n    margin_x, margin_y = view_w * 0.07, view_h * 0.09\\n    thick = view_h * 0.013\\n    x0 = -view_w / 2.0 + margin_x\\n    y0 = -view_h / 2.0 + margin_y\\n\\n    me = bpy.data.meshes.new(\\\"ScaleBar\\\" + suffix)\\n    verts = [(x0, y0, z), (x0 + length, y0, z), (x0 + length, y0 + thick, z), (x0, y0 + thick, z)]\\n    me.from_pydata(verts, [], [(0, 1, 2, 3)])\\n    me.update()\\n    me.materials.append(emission_material(\\\"ScaleBar\\\" + suffix, label_colour, 1.0))\\n    bar = bpy.data.objects.new(\\\"ScaleBar\\\" + suffix, me)\\n    scene.collection.objects.link(bar)\\n    bar.parent = cam\\n\\n    # \\\"50 \u00b5m\\\", not \\\"50 um\\\". Blender's default Bfont carries U+00B5, checked rather than hoped.\\n    txt = bpy.data.curves.new(\\\"ScaleBarLabel\\\" + suffix, type=\\\"FONT\\\")\\n    txt.body = (\\\"%g\\\" % length) + \\\" \u00b5m\\\"\\n    txt.size = view_h * 0.045\\n    txt.align_x = \\\"LEFT\\\"\\n    txt.align_y = \\\"BOTTOM\\\"\\n    txt.materials.append(emission_material(\\\"ScaleBarLabel\\\" + suffix, label_colour, 1.0))\\n    lab = bpy.data.objects.new(\\\"ScaleBarLabel\\\" + suffix, txt)\\n    lab.location = (x0, y0 + thick + view_h * 0.018, z)\\n    scene.collection.objects.link(lab)\\n    lab.parent = cam\\n    return length, bar, lab\\n\\n\\nHIDE_PATHS = (\\\"hide_viewport\\\", \\\"hide_render\\\")\\n\\n\\ndef key_hide(ob, pairs):\\n    \\\"\\\"\\\"Keyframe an object's visibility, CONSTANT so it switches rather than fades. pairs is\\n    [(frame, hidden), ...]; both hide_viewport and hide_render are keyed, because keying only one\\n    gives a scene that looks right in the viewport and renders wrong (or the reverse).\\n\\n    ONLY the two visibility curves are touched. The first version set every fcurve on the object\\n    to CONSTANT, which on the EM plane -- the one object here that is both animated and switched\\n    -- froze its travel as well, and the sections then shuffled in place instead of sweeping.\\\"\\\"\\\"\\n    for f, hide in pairs:\\n        ob.hide_viewport = ob.hide_render = bool(hide)\\n        ob.keyframe_insert(\\\"hide_viewport\\\", frame=max(int(f), 1))\\n        ob.keyframe_insert(\\\"hide_render\\\", frame=max(int(f), 1))\\n    if ob.animation_data and ob.animation_data.action:\\n        for fc in ob.animation_data.action.fcurves:\\n            if fc.data_path in HIDE_PATHS:\\n                for kp in fc.keyframe_points:\\n                    kp.interpolation = \\\"CONSTANT\\\"\\n\\n\\ndef em_box_blender(em, frame):\\n    \\\"\\\"\\\"(lo, hi) of the EM cutout's eight corners in BLENDER coordinates, or None if there is no\\n    cutout. The camera needs this before it knows whether there is any geometry at all: with the\\n    3D models switched off the EM box is the entire scene.\\\"\\\"\\\"\\n    if not em or not em.get(\\\"slices\\\") or int(em.get(\\\"count\\\", 0)) <= 0:\\n        return None\\n    ox, oy, oz = [float(v) for v in em[\\\"origin_um\\\"]]\\n    dx, dy, dz = [float(v) for v in em[\\\"size_um\\\"]]\\n    pts = np.array([[ox + a * dx, oy + b * dy, oz + c * dz]\\n                    for a in (0, 1) for b in (0, 1) for c in (0, 1)], dtype=np.float32)\\n    v, _ = to_blender_frame(pts, np.array([[0, 1, 2]], dtype=np.int32), frame)\\n    return v.min(axis=0), v.max(axis=0)\\n\\n\\ndef em_sweep_axis(frame):\\n    \\\"\\\"\\\"Which way the sections advance, in Blender coordinates. dataset +z through the frame\\n    transform: (0,-1,0) for a MICrONS export, so the sweep runs along the camera's view axis and\\n    can be watched face-on. Any frame where it comes out vertical instead cannot be staged that\\n    way -- the turntable spins about the same axis -- and the caller falls back.\\\"\\\"\\\"\\n    d, _ = to_blender_frame(np.array([[0.0, 0.0, 1.0]], dtype=np.float32),\\n                            np.array([[0, 0, 0]], dtype=np.int32), frame)\\n    return d[0]\\n\\n\\ndef add_em_stack(scene, em, base, start_frame, frame):\\n    \\\"\\\"\\\"The EM cutout as a plane that sweeps the sections TWICE. Returns (frames, act_two_start).\\n\\n    S\u00f8ren, in three passes, and the shape it settled into is worth reading in order:\\n\\n      \\\"first you have the EM running from the closest image to the furthest ... then when all the\\n       cells are visible, do the rotation\\\"\\n      \\\"The 3D model does not have to appear, it should be there the whole time while scrolling\\n       through the EM\\\"\\n      \\\"the EM with segmentation to first run from the back to the front without any 3D models\\n       showing, then run from the front to the back with the 3D models showing like it is now\\\"\\n\\n    So the plane makes TWO passes over the same sections:\\n\\n      ACT ZERO   back to front, no geometry at all. Just the tissue, and the segmentation painted\\n                 on it -- the reader gets to look at the data before anything is drawn on top of\\n                 it, which is the honest order for a figure that is arguing FROM the imagery.\\n      ACT ONE    front to back, geometry present. Identical to what act one has always been: the\\n                 models are simply there, and the plane retreating past them uncovers them.\\n\\n    The turn-around frame is shared, so the plane reaches the near face and reverses without a\\n    stutter, and that is exactly the frame the models appear on.\\n\\n    NEAR AND FAR ARE THE CAMERA'S, not the dataset's. During the sweep the camera looks along +Y in\\n    Blender, and Blender y = -dataset z, so the section nearest the lens is the one at the LARGEST\\n    dataset z. \\\"Back\\\" is therefore dataset z-min and act zero plays the sequence FORWARDS; act one\\n    runs the other way and plays it in reverse -- see the frame_offset animation below, which is\\n    the fiddly part.\\n\\n    \u2500\u2500 WHY A TEXTURED PLANE AND NOT A VOLUME \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\n    S\u00f8ren pointed at Microscopy Nodes (aafkegros/MicroscopyNodes), which does real volume\\n    rendering and does it well. It is not used here, for reasons that are about deployment rather\\n    than quality: it is a Blender extension the recipient has to install, its current release\\n    targets Blender 5.2 while this writes 4.5 so that the widest audience can open the file at\\n    all, and loading is documented only through its Scene Properties panel -- there is no\\n    published Python entry point to call from a headless Colab build. (Its repository does carry a\\n    tests/ directory, which suggests the loader IS drivable from a script; that is worth reading\\n    before ruling it out permanently.)\\n\\n    A textured plane needs no add-on, no particular Blender version and no volume data in the\\n    file, and it is what a section-by-section EM viewer actually is. The volumetric look is the\\n    upgrade path, not the starting point.\\n\\n    \u2500\u2500 THE ONE THING TO GET RIGHT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\n    Orientation. An EM cutout is nearly symmetric noise, so a mirrored or transposed mapping still\\n    looks like EM and nobody notices until a cell sits on the wrong side of a vessel. The UVs are\\n    laid out so v increases with DATASET Y, and make_test_em.py draws an asymmetric corner marker\\n    for exactly this reason -- the check is a picture, not an assertion about a matrix.\\n    \\\"\\\"\\\"\\n    pat = em.get(\\\"slices\\\")\\n    count = int(em.get(\\\"count\\\", 0))\\n    if not pat or count <= 0:\\n        return 0, 0\\n    first = int(em.get(\\\"first\\\", 1))\\n    # Two passes sharing their turn-around frame: 1..count out, count..2*count-1 back.\\n    act2_frame = start_frame + count - 1\\n    end_frame = start_frame + 2 * count - 2\\n    path0 = os.path.join(base, pat % first)\\n    if not os.path.exists(path0):\\n        print(\\\"  ! EM stack not found: \\\" + path0)\\n        return 0, 0\\n\\n    ox, oy, oz = [float(v) for v in em[\\\"origin_um\\\"]]\\n    dx, dy, dz = [float(v) for v in em[\\\"size_um\\\"]]\\n\\n    # The quad in DATASET micrometres at the near face, then through the same frame transform\\n    # everything else went through -- so the imagery lands where the cells are without a second,\\n    # separately-maintained idea of which way is up.\\n    quad = np.array([[ox, oy, oz], [ox + dx, oy, oz],\\n                     [ox + dx, oy + dy, oz], [ox, oy + dy, oz]], dtype=np.float32)\\n    # THE MANIFEST'S frame, not a hard-coded \\\"microns\\\". The first version assumed the EM would\\n    # always be MICrONS-framed, which is true of every real export and false of the synthetic test\\n    # -- so the cells sat in one frame and the sections in another, and the plane rendered six\\n    # frame-heights off the top of the picture. A transform that is right for the geometry has to\\n    # be the same transform used for everything placed among it.\\n    quad_b, _ = to_blender_frame(quad, np.array([[0, 1, 2]], dtype=np.int32), frame)\\n    step_b, _ = to_blender_frame(np.array([[0, 0, dz / max(count - 1, 1)]], dtype=np.float32),\\n                                 np.array([[0, 0, 0]], dtype=np.int32), frame)\\n    step = mathutils.Vector(tuple(float(v) for v in step_b[0]))\\n\\n    me = bpy.data.meshes.new(\\\"EM\\\")\\n    me.from_pydata([tuple(float(v) for v in p) for p in quad_b], [], [(0, 1, 2, 3)])\\n    me.update()\\n    # UVs tied to DATASET Y and to how a PNG is stored, not to whichever way the frame transform\\n    # happens to leave the quad pointing:\\n    #     PIL/PNG row 0            is the TOP of the image, and is dataset y = oy\\n    #     Blender's v = 1          is the TOP of the image\\n    # so v = 1 belongs to the two corners at y = oy, whatever the frame does to them afterwards.\\n    # The first version used the naive (0,0),(1,0),(1,1),(0,1) and put v = 0 -- the image's BOTTOM\\n    # row -- on the corner nearest the pia, flipping every section upside down. On EM noise with a\\n    # symmetric marker that would have shipped; make_test_em.py draws a deliberately asymmetric\\n    # corner so it could not.\\n    uv = me.uv_layers.new(name=\\\"UVMap\\\")\\n    for i, coord in enumerate([(0.0, 1.0), (1.0, 1.0), (1.0, 0.0), (0.0, 0.0)]):\\n        uv.data[i].uv = coord\\n\\n    mat = bpy.data.materials.new(\\\"EM\\\")\\n    mat.use_nodes = True\\n    nt = mat.node_tree\\n    nt.nodes.clear()\\n    out = nt.nodes.new(\\\"ShaderNodeOutputMaterial\\\")\\n    em_node = nt.nodes.new(\\\"ShaderNodeEmission\\\")\\n    em_node.inputs[1].default_value = 1.0\\n    tex = nt.nodes.new(\\\"ShaderNodeTexImage\\\")\\n    img = bpy.data.images.load(path0)\\n    img.source = \\\"SEQUENCE\\\"\\n    tex.image = img\\n    tex.extension = \\\"CLIP\\\"\\n    tex.interpolation = \\\"Closest\\\"     # a section is data; do not blur one into the next\\n    iu = tex.image_user\\n    # frame_duration IS NOT \\\"how many files there are\\\". Blender computes the local frame as\\n    # (scene_frame - frame_start + 1), CLAMPS it to [0, frame_duration], and only then adds\\n    # frame_offset. Left at `count`, every frame of act one past the turn-around clamped to 90,\\n    # the negative offset took the result below 1, and the plane rendered magenta -- an out-of-\\n    # range image looks exactly like a missing file. It has to span the scene frames the sequence\\n    # is shown for, not the number of sections.\\n    iu.frame_duration = end_frame - start_frame + 1\\n    iu.frame_start = start_frame\\n    iu.use_cyclic = False\\n    iu.use_auto_refresh = True\\n    # PLAYING A SEQUENCE FORWARDS AND THEN BACKWARDS, from one image_user. Blender has no\\n    # \\\"reverse\\\" switch on an image sequence; the displayed index is\\n    #     shown = frame_offset + (scene_frame - frame_start) + 1\\n    # and `scene_frame - frame_start` only ever counts up. So the direction lives entirely in\\n    # frame_offset:\\n    #     act zero   shown must count UP with the scene   -> offset HELD at first-1\\n    #     act one    shown must count DOWN                -> offset falls at twice the rate, so\\n    #                                                        the two slopes cancel to -1\\n    # The three keys below say exactly that, and they agree at the turn-around frame: both acts\\n    # want offset = first-1 there, which is what makes the reversal seamless rather than a jump.\\n    #\\n    # Obscure, so it is asserted rather than trusted -- the synthetic stack burns the slice number\\n    # into each section as a bar whose length grows with the index, so the bar must GROW through\\n    # act zero and SHRINK through act one, and be full at the turn.\\n    #\\n    # The alternative was to have the producer write the slices in play order, which keeps this\\n    # file simple and moves a silent, easy-to-invert convention into every producer instead. One\\n    # tested oddity here beats a convention that has to be remembered in three places.\\n    iu.frame_offset = first - 1\\n    iu.keyframe_insert(\\\"frame_offset\\\", frame=start_frame)\\n    iu.keyframe_insert(\\\"frame_offset\\\", frame=act2_frame)\\n    iu.frame_offset = (first - 1) - 2 * (count - 1)\\n    iu.keyframe_insert(\\\"frame_offset\\\", frame=end_frame)\\n    for fc in (tex.image_user.id_data.animation_data.action.fcurves\\n               if tex.image_user.id_data.animation_data else []):\\n        for kp in fc.keyframe_points:\\n            kp.interpolation = \\\"LINEAR\\\"\\n    nt.links.new(tex.outputs[\\\"Color\\\"], em_node.inputs[0])\\n    nt.links.new(em_node.outputs[0], out.inputs[0])\\n    me.materials.append(mat)\\n\\n    ob = bpy.data.objects.new(\\\"EM_sections\\\", me)\\n    scene.collection.objects.link(ob)\\n    # A PICTURE, NOT AN OCCLUDER. The sections are an emissive quad the size of the box, and left\\n    # in the shadow and bounce paths they both cast a hard shadow across whatever is behind them\\n    # and spill their own brightness onto the cells in front. Neither is a thing an EM section\\n    # does. Guarded with getattr: the flags are spelled the same in 4.x and 5.x but a missing one\\n    # should not take the build down.\\n    for flag in (\\\"visible_shadow\\\", \\\"visible_diffuse\\\", \\\"visible_glossy\\\", \\\"visible_volume_scatter\\\"):\\n        if hasattr(ob, flag):\\n            setattr(ob, flag, False)\\n\\n    # VISIBILITY IS KEYED BY THE CALLER, not here. It used to be keyed twice -- once here on a\\n    # guess, then again in build() once the acts were laid out -- and the second pass cleared the\\n    # object's whole action to do it, taking the plane's travel with it. One owner, one place.\\n\\n    # Built at dataset z = oz, which is the FAR face -- the back. Act zero walks it forward to the\\n    # near face; act one walks it back to where it was built.\\n    ob.location = (0.0, 0.0, 0.0)\\n    ob.keyframe_insert(\\\"location\\\", frame=start_frame)\\n    ob.location = tuple(step * (count - 1))\\n    ob.keyframe_insert(\\\"location\\\", frame=act2_frame)\\n    ob.location = (0.0, 0.0, 0.0)\\n    ob.keyframe_insert(\\\"location\\\", frame=end_frame)\\n    if ob.animation_data and ob.animation_data.action:\\n        for fc in ob.animation_data.action.fcurves:\\n            for kp in fc.keyframe_points:\\n                kp.interpolation = \\\"LINEAR\\\" if fc.data_path == \\\"location\\\" else \\\"CONSTANT\\\"\\n    return end_frame - start_frame + 1, act2_frame\\n\\n\\ndef add_ambient_floor(world, bg, ambient=0.14):\\n    \\\"\\\"\\\"A dim ambient for everything EXCEPT what the camera sees behind the scene.\\n\\n    The background is \u00b5Jump's #0d1117 and has to stay exactly that -- it is the whole point of the\\n    colour having been chosen. But a world that dark also lights nothing, so a surface the three\\n    suns and the headlight all miss renders pure black, and \\\"black\\\" and \\\"a hole in the picture\\\"\\n    look the same.\\n\\n    Light Path > Is Camera Ray separates the two jobs the world does. A ray straight from the lens\\n    into the void gets the dark background; every other ray -- the ones that light surfaces -- gets\\n    a neutral grey at `ambient`. Nothing in frame can be blacker than that, and the background is\\n    untouched. Asserted rather than assumed: build() renders a corner pixel and checks it is still\\n    (13, 17, 23).\\n\\n    Kept small on purpose. Ambient is a floor, not lighting: raise it and every membrane loses the\\n    contrast the three-point rig is there to give it.\\\"\\\"\\\"\\n    nt = world.node_tree\\n    out = next((n for n in nt.nodes if n.type == \\\"OUTPUT_WORLD\\\"), None)\\n    if out is None:\\n        return None\\n    amb = nt.nodes.new(\\\"ShaderNodeBackground\\\")\\n    amb.inputs[0].default_value = (ambient, ambient, ambient, 1.0)\\n    amb.inputs[1].default_value = 1.0\\n    mix = nt.nodes.new(\\\"ShaderNodeMixShader\\\")\\n    path = nt.nodes.new(\\\"ShaderNodeLightPath\\\")\\n    is_cam = path.outputs.get(\\\"Is Camera Ray\\\")\\n    if is_cam is None:\\n        return None\\n    # Fac 0 -> input 1, Fac 1 -> input 2. Camera rays (Fac 1) must land on the dark background.\\n    nt.links.new(is_cam, mix.inputs[0])\\n    nt.links.new(amb.outputs[0], mix.inputs[1])\\n    nt.links.new(bg.outputs[0], mix.inputs[2])\\n    nt.links.new(mix.outputs[0], out.inputs[\\\"Surface\\\"])\\n    return mix\\n\\n\\ndef add_turntable(scene, cam, centre, frames, fps, start_frame=1):\\n    \\\"\\\"\\\"One full revolution in `frames`, looping seamlessly.\\n\\n    The camera is parented to an empty at the scene's centre and the EMPTY spins; the camera never\\n    moves relative to it, so it stays aimed at the centre for free and the scale bar (parented to\\n    the camera) rides along.\\n\\n    The 360 degrees are keyed at frame `frames + 1`, NOT at `frames`. Rendering 1..frames then\\n    gives `frames` distinct pictures whose last one is one step short of the first -- so the loop\\n    closes. Keying 360 at the last rendered frame instead would render frame 1 and frame `frames`\\n    identically and the video would stutter once per revolution.\\\"\\\"\\\"\\n    pivot = bpy.data.objects.new(\\\"Turntable\\\", None)\\n    pivot.empty_display_type = \\\"PLAIN_AXES\\\"\\n    pivot.empty_display_size = 1.0\\n    pivot.location = tuple(float(x) for x in centre)\\n    scene.collection.objects.link(pivot)\\n\\n    world_loc = mathutils.Vector(tuple(cam.location))\\n    cam.parent = pivot\\n    cam.location = world_loc - mathutils.Vector(tuple(float(x) for x in centre))\\n    cam.rotation_euler = (-mathutils.Vector(cam.location)).to_track_quat(\\\"-Z\\\", \\\"Y\\\").to_euler()\\n\\n    pivot.rotation_euler = (0.0, 0.0, 0.0)\\n    pivot.keyframe_insert(\\\"rotation_euler\\\", index=2, frame=start_frame)\\n    pivot.rotation_euler = (0.0, 0.0, 2.0 * math.pi)\\n    pivot.keyframe_insert(\\\"rotation_euler\\\", index=2, frame=start_frame + frames)\\n    # Linear, or the turntable eases in and out of a rotation that has no beginning or end.\\n    for fc in pivot.animation_data.action.fcurves:\\n        for kp in fc.keyframe_points:\\n            kp.interpolation = \\\"LINEAR\\\"\\n    pivot.rotation_euler = (0.0, 0.0, 0.0)\\n\\n    scene.frame_start, scene.frame_end, scene.frame_current = 1, start_frame + frames - 1, 1\\n    scene.render.fps = fps\\n    return pivot\\n\\n\\ndef camera_pose(centre, distance, elev):\\n    \\\"\\\"\\\"Where the camera sits and how it is turned, for one elevation above the EM plane's normal.\\n\\n    Returned rather than derived with to_track_quat because the sweep pose is elevation ZERO --\\n    dead face-on to the sections -- and \\\"point -Z along +Y, keep +Y up\\\" is degenerate exactly\\n    there: the up vector it is asked to preserve is the axis it is asked to look down, so the roll\\n    is whatever the library falls back to. The closed form has no such case, and for the elevated\\n    pose it agrees with to_track_quat to the last bit.\\\"\\\"\\\"\\n    off = (0.0, -distance * math.cos(elev), distance * math.sin(elev))\\n    rot = (math.pi / 2.0 - elev, 0.0, 0.0)\\n    return [float(centre[i]) + off[i] for i in range(3)], off, rot\\n\\n\\ndef own_action(idblock, name, id_type):\\n    \\\"\\\"\\\"Give the camera DATA an Action of its own, with its own slot, before anything is keyed.\\n\\n    THE FOUR-DELIVERY BUG. Blender 4.4 replaced Actions with SLOTTED Actions: one Action can hold\\n    the animation of several datablocks, one slot each. `keyframe_insert` on an ID whose owning\\n    object is already animated does not make a new Action -- it adds a SLOT to the object's. So\\n\\n        cam.keyframe_insert(\\\"location\\\")          -> creates \\\"CameraAction\\\", slot OBCamera\\n        cam.data.keyframe_insert(\\\"ortho_scale\\\")  -> adds slot CACamera to THE SAME Action\\n\\n    leaving one Action with `id_root = 'OBJECT'` carrying a camera-data slot. Renaming the camera\\n    data is not enough; the reuse is by owner, not by name. In the session that built the file\\n    everything evaluates -- which is why every preview render was correct, and why \\\"the preview\\n    looks like it worked\\\" was the truest thing said about this bug -- but on re-opening elsewhere\\n    the object slot rebinds and the camera-data slot need not. Location and rotation animate, the\\n    pan is visible; ortho_scale does not, and the camera never widens. No error anywhere.\\n\\n    Assigning the Action first forces keyframe_insert to use it, and the result carries\\n    `id_root = 'CAMERA'`. Verified through a save/reload here: 5 -> 23.77 -> 50 across ten frames.\\n\\n    The reuse works in BOTH directions, which the check caught on the first attempt at this fix:\\n    claiming an Action for the camera data first made the camera OBJECT'S later keyframe_insert\\n    join THAT one instead. So both are claimed explicitly, up front, before a single key is set.\\n\\n    Guarded, because `action.slots` only exists from 4.4. On an older Blender there are no slots\\n    to collide and assigning the Action alone is the whole job.\\\"\\\"\\\"\\n    ad = idblock.animation_data or idblock.animation_data_create()\\n    act = bpy.data.actions.new(name)\\n    ad.action = act\\n    if hasattr(act, \\\"slots\\\"):\\n        try:\\n            ad.action_slot = act.slots.new(id_type=id_type, name=idblock.name)\\n        except Exception as e:                       # pragma: no cover -- version drift\\n            print(\\\"  ! could not give %s its own action slot (%s); its animation may not \\\"\\n                  \\\"survive re-opening this file\\\" % (idblock.name, e))\\n    return act\\n\\n\\ndef add_pull_back(cam, pivot, em_centre, geo_centre, distance, elev,\\n                  ortho_sweep, ortho_turn, em_frames, zoom_frames):\\n    \\\"\\\"\\\"Hold the sweep framing, then pull back into the turntable framing.\\n\\n    S\u00f8ren: \\\"I also want the zoom to be full screen on the EM when it scrolls through that, but if\\n    the 3D models are larger than the EM, then it should zoom out before rotating around it.\\\"\\n\\n    So the animation has a hinge in it, and four things move across it together:\\n\\n      ortho_scale     tight on the EM sections -> wide enough for the whole cell set\\n      elevation       0 (face-on to the sections) -> the turntable's 22 degrees\\n      pivot location  the EM box's centre -> the geometry's centre\\n      camera offset   straight back -> back and up\\n\\n    ELEVATION IS PART OF IT, and that is not decoration. Under an orthographic camera tilted by\\n    `elev`, a plane travelling `dz` along the view axis slides `dz * sin(elev)` up the frame as it\\n    goes: at 22 degrees over a 110 um sweep that is 41 um of drift, a quarter of the plane's own\\n    height. \\\"Full screen on the EM\\\" is only true, rather than nearly true, if the sweep is watched\\n    face-on -- and face-on to a series of sections is how anyone looks at EM anyway.\\n\\n    Every value is keyed twice before the hinge (frame 1 and `em_frames`) so act one is a HOLD and\\n    not a slow drift from the first frame onwards. Bezier, not linear: a pull-back that starts and\\n    stops abruptly reads as a cut.\\\"\\\"\\\"\\n    a_loc, a_off, a_rot = camera_pose(em_centre, distance, 0.0)\\n    b_loc, b_off, b_rot = camera_pose(geo_centre, distance, elev)\\n    end = em_frames + zoom_frames\\n    # BOTH, and BEFORE the first key of either -- see own_action's docstring. Claiming only one\\n    # of them just moves the sharing to the other side.\\n    own_action(cam, \\\"CameraAction\\\", \\\"OBJECT\\\")\\n    own_action(cam.data, \\\"CameraLensAction\\\", \\\"CAMERA\\\")\\n\\n    for f, (piv, off, rot, ortho) in (\\n            (1, (em_centre, a_off, a_rot, ortho_sweep)),\\n            (em_frames, (em_centre, a_off, a_rot, ortho_sweep)),\\n            (end, (geo_centre, b_off, b_rot, ortho_turn))):\\n        pivot.location = tuple(float(v) for v in piv)\\n        pivot.keyframe_insert(\\\"location\\\", frame=f)\\n        cam.location = off\\n        cam.keyframe_insert(\\\"location\\\", frame=f)\\n        cam.rotation_euler = rot\\n        cam.keyframe_insert(\\\"rotation_euler\\\", frame=f)\\n        cam.data.ortho_scale = ortho\\n        cam.data.keyframe_insert(\\\"ortho_scale\\\", frame=f)\\n\\n    # Leave the objects in their FINAL pose. The keyframes decide what plays, but a .blend that\\n    # opens on frame 1 with the camera parked somewhere it never sits is confusing to inspect.\\n    pivot.location = tuple(float(v) for v in geo_centre)\\n    cam.location = b_off\\n    cam.rotation_euler = b_rot\\n    # THE STORED ortho_scale IS THE SWEEP'S, not the turntable's, and that is deliberate. It is\\n    # what any Blender falls back to if this camera's animation is ever not applied -- and one\\n    # such failure cost four rounds (see the camera-data naming note in build()). Falling back to\\n    # the tight framing means a correct EM sweep and a pull-back that holds its size; falling back\\n    # to the wide one would mean an EM sweep that is wrong from frame 1. The revolution does not\\n    # depend on either: it is shot on Camera_turn, whose ortho_scale is a plain static number.\\n    cam.data.ortho_scale = ortho_sweep\\n    return end\\n\\n\\ndef active_camera(scene, frame):\\n    \\\"\\\"\\\"Which camera renders `frame`, markers included.\\n\\n    Blender switches cameras on marker-bound timeline markers, and `scene.camera` follows along\\n    when the frame changes in the UI. Resolved by hand here rather than trusted, because the\\n    reports that matter are printed from a background build where nothing has drawn a viewport,\\n    and a framing check that measures the WRONG camera is worse than no check.\\\"\\\"\\\"\\n    bound = [m for m in scene.timeline_markers if m.camera and m.frame <= frame]\\n    return max(bound, key=lambda m: m.frame).camera if bound else scene.camera\\n\\n\\ndef render_contact_sheet(scene, frames, out_png, tile_w=600, tile_h=338, samples=24, gap=6):\\n    \\\"\\\"\\\"Four moments of the animation in one picture, instead of one.\\n\\n    \u2500\u2500 WHY THIS REPLACED A SINGLE STILL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\n    S\u00f8ren reported four times, over three deliveries, that the camera \\\"does not zoom out while\\n    panning to the center of the figure before rotating\\\". Every check here says it does: the\\n    saved .blend is re-opened, stepped frame by frame, and its ortho_scale read back widening\\n    from the sweep framing to the turntable framing. Twice I answered from those numbers, and\\n    twice that was worth nothing to him, because a number in a log is not the thing he is\\n    looking at -- and a still of ONE frame cannot show a change that happens BETWEEN frames.\\n\\n    The likeliest explanation for the gap is that an animation is being judged from the 3D\\n    viewport rather than through the camera (Numpad 0). In the viewport the pan is plainly\\n    visible -- the camera object slides across the screen -- and the zoom is INVISIBLE, because\\n    zoom is a property of the lens, not a movement of anything. That produces exactly the report:\\n    it pans, it does not zoom, and most of the scene is out of view during the rotation.\\n\\n    Rather than say so again, the export now ships the evidence. Four renders, through the camera,\\n    at the four moments that matter, side by side with their ortho_scale printed underneath in the\\n    log. If the last two panels show the whole cell set and the first two are tight on the EM, the\\n    file is right whatever the viewport is doing; and if they do not, there is finally a picture of\\n    the fault to look at.\\n\\n    Same total pixels as the single 1200x675 preview it replaces, so it costs about the same.\\n\\n    NO PIL. This runs inside Blender's own Python, which does not ship Pillow -- the tiling is\\n    numpy over bpy.data.images. Pixels come back bottom-row-first and linearised from sRGB;\\n    writing them into a new sRGB image and saving re-encodes them, so the round trip is exact.\\\"\\\"\\\"\\n    bg = hex_rgba(UJUMP_BG, 1.0)\\n    r = scene.render\\n    r.image_settings.file_format = \\\"PNG\\\"\\n    r.image_settings.color_mode = \\\"RGB\\\"\\n    r.resolution_x, r.resolution_y, r.resolution_percentage = tile_w, tile_h, 100\\n    try:\\n        scene.eevee.taa_render_samples = samples\\n    except AttributeError:\\n        pass\\n\\n    cols = 2\\n    rows = (len(frames) + cols - 1) // cols\\n    W = cols * tile_w + (cols - 1) * gap\\n    H = rows * tile_h + (rows - 1) * gap\\n    sheet = np.zeros((H, W, 4), dtype=np.float32)\\n    sheet[..., 0], sheet[..., 1], sheet[..., 2], sheet[..., 3] = bg[0], bg[1], bg[2], 1.0\\n\\n    tmp = tempfile.gettempdir()\\n    for i, f in enumerate(frames):\\n        scene.frame_set(int(f))\\n        bpy.context.view_layer.update()\\n        p = os.path.join(tmp, \\\"blendscene_panel_%d.png\\\" % i)\\n        r.filepath = p\\n        bpy.ops.render.render(write_still=True)\\n        im = bpy.data.images.load(p)\\n        a = np.array(im.pixels[:], dtype=np.float32).reshape(im.size[1], im.size[0], 4)\\n        bpy.data.images.remove(im)\\n        # Row 0 of `a` is the BOTTOM of the render. The sheet is built the same way up, so the\\n        # top row of tiles lives at the high end of the array.\\n        cx, cy = i % cols, i // cols\\n        y0 = (rows - 1 - cy) * (tile_h + gap)\\n        x0 = cx * (tile_w + gap)\\n        sheet[y0:y0 + a.shape[0], x0:x0 + a.shape[1], :] = a\\n\\n    out = bpy.data.images.new(\\\"contact_sheet\\\", width=W, height=H, alpha=False)\\n    out.pixels = sheet.reshape(-1)\\n    out.filepath_raw = os.path.abspath(out_png)\\n    out.file_format = \\\"PNG\\\"\\n    out.save()\\n    bpy.data.images.remove(out)\\n    return os.path.abspath(out_png)\\n\\n\\ndef set_video_output(scene, out_blend, frames, fps, suffix=\\\"_turntable\\\"):\\n    \\\"\\\"\\\"H.264 in an MP4, which is what PowerPoint plays without being asked twice.\\n\\n    Written next to the .blend via Blender's `//` relative prefix, so pressing Ctrl+F12 puts the\\n    video beside the scene rather than somewhere in a temp directory. Audio is explicitly NONE:\\n    an empty audio track is a common reason a file plays everywhere except in PowerPoint.\\\"\\\"\\\"\\n    r = scene.render\\n    r.engine = \\\"BLENDER_EEVEE_NEXT\\\" if \\\"BLENDER_EEVEE_NEXT\\\" in {\\n        i.identifier for i in type(r).bl_rna.properties[\\\"engine\\\"].enum_items} else \\\"BLENDER_EEVEE\\\"\\n    r.resolution_x, r.resolution_y, r.resolution_percentage = 1920, 1080, 100\\n    r.fps = fps\\n    r.image_settings.file_format = \\\"FFMPEG\\\"\\n    r.ffmpeg.format = \\\"MPEG4\\\"\\n    r.ffmpeg.codec = \\\"H264\\\"\\n    r.ffmpeg.constant_rate_factor = \\\"HIGH\\\"\\n    r.ffmpeg.ffmpeg_preset = \\\"GOOD\\\"\\n    r.ffmpeg.audio_codec = \\\"NONE\\\"\\n    r.filepath = \\\"//\\\" + os.path.splitext(os.path.basename(out_blend))[0] + suffix + \\\".mp4\\\"\\n    try:\\n        scene.eevee.taa_render_samples = 32\\n    except AttributeError:\\n        pass\\n    return r.filepath\\n\\n\\ndef sub_collection(parent, name):\\n    c = bpy.data.collections.get(name)\\n    if c is None:\\n        c = bpy.data.collections.new(name)\\n        parent.children.link(c)\\n    return c\\n\\n\\n# \u2500\u2500 which way is up \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n# MICrONS/Neuroglancer Y increases DOWNWARD -- image-row order, so +Y is deeper into cortex and\\n# the pia sits at small Y. Loaded raw, a cortical column arrives in Blender lying on its side and\\n# upside down, which is a bad first impression of an otherwise correct scene.\\n#\\n# The transform below is not invented here. It is exactly what \u00b5Jump's own \\\"3D model\\\" button\\n# already produces, composed with what Blender's glTF importer already does to it:\\n#\\n#   core/mesh.js flipYForGLTF()   dataset (x, y, z) -> glTF (x, -y, z), winding swapped\\n#   Blender glTF import          glTF   (x, y, z) -> Blender (x, -z, y)\\n#   net                          dataset (x, y, z) -> Blender (x, -z, -y)\\n#\\n# So a .blend built this way sits in the same orientation as the .glb S\u00f8ren already downloads per\\n# cell, and the two can be opened side by side. The net matrix has determinant -1 (it is a\\n# reflection, not a rotation), so face winding is swapped once to keep normals pointing out --\\n# skip that and every surface renders inside-out, which on a translucent membrane is not subtle.\\nCOORD_FRAMES = {\\n    \\\"blender\\\": None,                       # already in Blender axes; used by the synthetic test\\n    \\\"microns\\\": \\\"flip_yz\\\",                  # MICrONS / V1DD / any Neuroglancer precomputed source\\n}\\n\\n\\ndef to_blender_frame(v, f, frame):\\n    if COORD_FRAMES.get(frame) != \\\"flip_yz\\\":\\n        return v, f\\n    out = np.empty_like(v)\\n    out[:, 0] = v[:, 0]\\n    out[:, 1] = -v[:, 2]\\n    out[:, 2] = -v[:, 1]\\n    return out, f[:, [0, 2, 1]]\\n\\n\\ndef load_npz(base, rel):\\n    if not rel:\\n        return None\\n    p = rel if os.path.isabs(rel) else os.path.join(base, rel)\\n    if not os.path.exists(p):\\n        print(\\\"  ! missing mesh file: \\\" + p)\\n        return None\\n    z = np.load(p)\\n    v = np.asarray(z[\\\"verts\\\"], dtype=np.float32)\\n    f = np.asarray(z[\\\"faces\\\"], dtype=np.int32)\\n    if v.ndim != 2 or v.shape[1] != 3 or f.ndim != 2 or f.shape[1] != 3:\\n        print(\\\"  ! %s: expected verts (N,3) and faces (M,3), got %s and %s\\\"\\n              % (rel, v.shape, f.shape))\\n        return None\\n    if len(f) and f.max() >= len(v):\\n        print(\\\"  ! %s: face index %d with only %d vertices\\\" % (rel, f.max(), len(v)))\\n        return None\\n    return v, f\\n\\n\\n# \u2500\u2500 the scene \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\ndef build(manifest_path, out_blend, preview_png=None):\\n    base = os.path.dirname(os.path.abspath(manifest_path))\\n    man = json.load(open(manifest_path, encoding=\\\"utf-8\\\"))\\n    units = man.get(\\\"units\\\", UNITS_UM)\\n    frame = man.get(\\\"frame\\\", \\\"blender\\\")\\n    if frame not in COORD_FRAMES:\\n        sys.exit(\\\"manifest frame %r is not one of %s\\\" % (frame, sorted(COORD_FRAMES)))\\n    if units != UNITS_UM:\\n        sys.exit(\\\"manifest units are %r; this script only builds micrometre scenes. Convert \\\"\\n                 \\\"before writing the manifest, so one file has one meaning.\\\" % units)\\n\\n    bpy.ops.wm.read_factory_settings(use_empty=True)\\n    scene = bpy.context.scene\\n    scene.name = (man.get(\\\"dataset\\\") or \\\"cells\\\")[:60]\\n\\n    # 1 unit = 1 \u00b5m, and Blender's readouts say so.\\n    us = scene.unit_settings\\n    us.system = \\\"METRIC\\\"\\n    us.scale_length = 1e-6\\n    try:\\n        us.length_unit = \\\"MICROMETERS\\\"\\n    except TypeError:\\n        pass                                    # older builds spell it differently; harmless\\n\\n    colors = man.get(\\\"colors\\\") or {}\\n    root_cells = sub_collection(scene.collection, \\\"Cells\\\")\\n    root_nuclei = sub_collection(scene.collection, \\\"Nuclei\\\")\\n\\n    lo = np.array([np.inf] * 3, dtype=np.float64)\\n    hi = np.array([-np.inf] * 3, dtype=np.float64)\\n    n_cells = n_nuclei = 0\\n    total_v = 0\\n    missing = []\\n\\n    # \u2500\u2500 how see-through is a cell? \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # S\u00f8ren: \\\"if the nuclei are included, then the cells should be transparent (like now), if not\\n    # included then they should not be transparent.\\\"\\n    #\\n    # So it is not a setting, it is a consequence: the transparency exists to let you see the\\n    # nucleus, and with no nucleus in the file it costs contrast and gives nothing back. Inferred\\n    # from what the manifest actually carries rather than from a flag, so the producer cannot say\\n    # one thing and ship another; `cell_alpha` in the manifest overrides it if a caller has a\\n    # reason.\\n    # Everything the reader is meant to see, so act zero can hide the lot and act one can bring\\n    # it back. One list rather than a walk of the collections later: the collections also hold the\\n    # camera's furniture, and hiding the scale bar during act zero would be a quiet regression.\\n    geo_objects = []\\n\\n    has_nuclei = any(c.get(\\\"nucleus_npz\\\")\\n                     and os.path.exists(os.path.join(base, c[\\\"nucleus_npz\\\"]))\\n                     for c in man.get(\\\"cells\\\", []))\\n    cell_alpha = float(man.get(\\\"cell_alpha\\\", CELL_ALPHA if has_nuclei else 1.0))\\n\\n    for c in man.get(\\\"cells\\\", []):\\n        ctype = c.get(\\\"type\\\") or \\\"Unclassified\\\"\\n        colour = colors.get(ctype, \\\"#888888\\\")\\n        name = c.get(\\\"name\\\") or (\\\"cell_\\\" + str(c.get(\\\"root_id\\\", \\\"?\\\")))\\n\\n        cell = load_npz(base, c.get(\\\"cell_npz\\\"))\\n        nuc = load_npz(base, c.get(\\\"nucleus_npz\\\"))\\n\\n        if cell is not None:\\n            v, f = to_blender_frame(cell[0], cell[1], frame)\\n            mat = make_material(\\\"cell_\\\" + ctype, colour, cell_alpha, cell_alpha < 1.0)\\n            geo_objects.append(add_mesh(name, v, f, mat, sub_collection(root_cells, ctype)))\\n            lo = np.minimum(lo, v.min(axis=0)); hi = np.maximum(hi, v.max(axis=0))\\n            n_cells += 1; total_v += len(v)\\n        elif c.get(\\\"cell_npz\\\"):\\n            missing.append(name + \\\" (cell)\\\")\\n\\n        if nuc is not None:\\n            v, f = to_blender_frame(nuc[0], nuc[1], frame)\\n            # The nucleus is opaque and a little darker than its cell, so the two read as the\\n            # same identity without the nucleus looking like a second, brighter cell.\\n            mat = make_material(\\\"nucleus_\\\" + ctype, colour, 1.0, False)\\n            geo_objects.append(\\n                add_mesh(\\\"Nucleus_\\\" + name, v, f, mat, sub_collection(root_nuclei, ctype)))\\n            lo = np.minimum(lo, v.min(axis=0)); hi = np.maximum(hi, v.max(axis=0))\\n            n_nuclei += 1; total_v += len(v)\\n        elif c.get(\\\"nucleus_npz\\\"):\\n            missing.append(name + \\\" (nucleus)\\\")\\n\\n    # \u2500\u2500 the blood vessels \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # S\u00f8ren: \\\"I would like that vasculature to be used in the colab script for the blender file if\\n    # a check box is ticked that includes the vasculature.\\\"\\n    #\\n    # Wan & Wei's TriSAM segmentation of minnie65, cut to this box and surfaced by the notebook\\n    # (see vasc_mesh.py). It is NOT filed under `cells`, deliberately: the cells list means \\\"cells\\n    # the filter matched\\\", it is what the type colours and the counts are keyed on, and a vessel\\n    # tree is neither a cell nor a type. Its own manifest key, its own collection, its own colour.\\n    #\\n    # ALWAYS TRANSLUCENT, whether or not there are nuclei. A vessel in a 60 \u00b5m box is a fat tube\\n    # running through the middle of everything; opaque, it hides the cells the scene is about.\\n    # Cells go see-through to show a nucleus inside them; the vasculature goes see-through to stop\\n    # it being a wall.\\n    vasc = man.get(\\\"vasculature\\\") or {}\\n    n_vasc_v = 0\\n    if vasc.get(\\\"npz\\\"):\\n        vm = load_npz(base, vasc[\\\"npz\\\"])\\n        if vm is not None:\\n            v, f = to_blender_frame(vm[0], vm[1], frame)\\n            mat = make_material(\\\"vasculature\\\", vasc.get(\\\"color\\\", \\\"#b03a48\\\"),\\n                                float(vasc.get(\\\"alpha\\\", 0.30)), True)\\n            geo_objects.append(add_mesh(\\\"Vasculature\\\", v, f, mat,\\n                                        sub_collection(scene.collection, \\\"Vasculature\\\")))\\n            lo = np.minimum(lo, v.min(axis=0)); hi = np.maximum(hi, v.max(axis=0))\\n            n_vasc_v = len(v); total_v += len(v)\\n        else:\\n            missing.append(\\\"vasculature\\\")\\n\\n    # \u2500\u2500 the EM box, in the same frame as everything else \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # Needed before the camera whether or not there is any geometry, because with the 3D models\\n    # switched off the EM box IS the scene. S\u00f8ren: \\\"If the mesh is not included, then it should\\n    # just scroll through the EM.\\\"\\n    em = man.get(\\\"em\\\") or {}\\n    em_box = em_box_blender(em, frame)\\n    has_geo = bool(np.isfinite(lo).all())\\n    if not has_geo:\\n        if em_box is None:\\n            sys.exit(\\\"nothing to build: no mesh in the manifest loaded, and no EM block either\\\")\\n        lo, hi = em_box[0].copy(), em_box[1].copy()\\n\\n    centre = (lo + hi) / 2.0\\n    span = float(np.max(np.maximum(hi - lo, 1e-6)))\\n\\n    # \u2500\u2500 the .glb comes out HERE, before any furniture \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # Written before the camera, lights and scale bar exist so it contains cells and nuclei and\\n    # nothing else. Exporting after would put a text object and an emissive rectangle into a file\\n    # whose whole job is to be the geometry.\\n    glb = os.path.splitext(os.path.abspath(out_blend))[0] + \\\".glb\\\"\\n    try:\\n        bpy.ops.export_scene.gltf(filepath=glb, export_format=\\\"GLB\\\",\\n                                  export_apply=True, export_cameras=False, export_lights=False,\\n                                  use_visible=True)\\n        print(\\\"%-22s %s\\\" % (\\\"also wrote\\\", glb))\\n    except Exception as e:\\n        print(\\\"%-22s %s\\\" % (\\\"glb export failed\\\", e))\\n\\n    # \u2500\u2500 act one, built before the camera because the camera is framed on it \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # After the .glb export, deliberately: the sections are an image sequence and have no business\\n    # in a geometry file.\\n    # Laid out before the camera because the camera is framed on it. The frame the plane\\n    # disappears on is not known yet -- it depends on whether there is a pull-back at all -- so\\n    # the object is kept and re-keyed below once the acts are decided.\\n    em_frames, act_two = add_em_stack(scene, em, base, 1, frame)\\n    if not em_frames:\\n        em_box = None                 # the manifest promised sections that are not on disk\\n\\n    # \u2500\u2500 act zero shows the tissue alone \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # S\u00f8ren: \\\"first run from the back to the front without any 3D models showing, then run from\\n    # the front to the back with the 3D models showing like it is now.\\\" So every cell and nucleus\\n    # is hidden for the outward pass and switched on at the turn-around frame -- CONSTANT\\n    # interpolation, because a fade would make it an effect and this is a change of subject.\\n    if em_frames and act_two > 1:\\n        for ob in geo_objects:\\n            key_hide(ob, [(1, True), (act_two, False)])\\n\\n    # \u2500\u2500 camera, light, world \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # \u2500\u2500 THE CAMERA DATA IS NAMED DIFFERENTLY FROM THE CAMERA OBJECT, AND THAT IS THE BUG FIX \u2500\u2500\\n    #\\n    # S\u00f8ren, five times over four deliveries: the camera pans to the cell but never widens, so the\\n    # revolution shows a tenth of the cell. Every measurement said the file was right. It was not,\\n    # and this line is why.\\n    #\\n    # Blender 4.4 replaced Actions with SLOTTED actions: one Action can hold the animation of\\n    # several datablocks, one slot each. `keyframe_insert` names the Action it creates after the\\n    # datablock -- and the camera OBJECT and the camera DATA were both called \\\"Camera\\\", so the\\n    # second call found the first call's \\\"CameraAction\\\" and added a slot to it instead of making\\n    # its own. Dumped out of a built file:\\n    #\\n    #   Camera OBJ   action='CameraAction' id_root='OBJECT' slot='OBCamera'\\n    #   Camera DATA  action='CameraAction' id_root='OBJECT' slot='CACamera'\\n    #                                      ^^^^^^^^^^^^^^^^\\n    #\\n    # One Action, id_root OBJECT, carrying a CAMERA slot. In the session that builds it everything\\n    # evaluates, which is why the preview render -- taken before the file is ever re-opened -- was\\n    # always correct, and why \\\"the preview looks like it worked\\\" was the truest thing said about\\n    # this bug. Re-opened elsewhere, the object slot rebinds and the camera-data slot need not, so\\n    # location and rotation animate (the pan he could see) and ortho_scale does not (the zoom he\\n    # could not). Exactly the asymmetry he reported, every single time.\\n    #\\n    # Naming the data \\\"CameraLens\\\" makes keyframe_insert create \\\"CameraLensAction\\\" -- a separate\\n    # Action with its own id_root -- and there is nothing left to share. Checked in build() and in\\n    # blendscenecheck.py, because a name collision is not the sort of thing anyone notices twice.\\n    cam_data = bpy.data.cameras.new(\\\"CameraLens\\\")\\n    cam_data.clip_start = 0.01\\n    cam_data.clip_end = max(span * 20.0, 1000.0)\\n    # ORTHOGRAPHIC, so the scale bar is true everywhere in frame rather than at one depth. See the\\n    # block comment above nice_scale_bar_length().\\n    cam_data.type = \\\"ORTHO\\\"\\n    cam = bpy.data.objects.new(\\\"Camera\\\", cam_data)\\n    scene.collection.objects.link(cam)\\n    # Aim with to_track_quat, not hand-rolled Euler angles. The first version of this computed the\\n    # two angles by trigonometry, got one of them wrong, and rendered a preview of the empty world\\n    # background -- geometry present and correct, camera pointing at nothing. mathutils has the\\n    # exact operation (\\\"point local -Z at this, keep +Y up\\\") and it is not worth re-deriving.\\n    #\\n    # The framing has to hold for EVERY angle of the turntable, not just this one, so it is sized\\n    # on the HORIZONTAL DIAGONAL of the bounding box -- the widest the scene can ever present as it\\n    # spins -- and on the vertical extent corrected for the frame's aspect. Sizing it on the view\\n    # from here would clip the corners a quarter-turn later.\\n    ext = hi - lo\\n    aspect = 1920.0 / 1080.0\\n    elev = math.radians(22.0)\\n    # Worst case over a whole revolution, in both screen axes:\\n    #   ACROSS  the box's horizontal diagonal -- the widest face it can ever turn towards you\\n    #   UP      its height, foreshortened by the elevation, PLUS the depth the tilt lifts into\\n    #           view: dz*cos(el) + diagonal*sin(el)\\n    # The first version left the elevation out of the vertical term and the framing check caught\\n    # it immediately -- 4 of 8 corners in frame. That check exists for exactly this.\\n    diag = math.hypot(float(ext[0]), float(ext[1]))\\n    half_w_need = 0.5 * diag\\n    half_h_need = 0.5 * (float(ext[2]) * math.cos(elev) + diag * math.sin(elev))\\n    ortho_turn = 2.0 * max(half_w_need, half_h_need * aspect) * 1.06\\n\\n    # \u2500\u2500 the sweep's own framing \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # S\u00f8ren: \\\"I want the zoom to be full screen on the EM when it scrolls through that.\\\" Face-on\\n    # (see add_pull_back) the section is a rectangle of exactly the box's Blender x and z extent,\\n    # so filling the frame is arithmetic rather than a guess. 1.02 rather than 1.06: this one is\\n    # meant to be tight.\\n    stage_em = False\\n    ortho_sweep, em_centre = ortho_turn, centre\\n    if em_box is not None and abs(float(em_sweep_axis(frame)[2])) < 0.5:\\n        eb_lo, eb_hi = em_box\\n        em_centre = (eb_lo + eb_hi) / 2.0\\n        w_em, h_em = float(eb_hi[0] - eb_lo[0]), float(eb_hi[2] - eb_lo[2])\\n        ortho_sweep = 2.0 * max(0.5 * w_em, 0.5 * h_em * aspect) * 1.02\\n        stage_em = True\\n    elif em_box is not None:\\n        print(\\\"  ! the sections advance along the turntable's own axis in this frame; \\\"\\n              \\\"keeping one camera pose for the whole animation\\\")\\n\\n    # Never zoom IN to rotate. If the cells are smaller than the EM box the sweep framing already\\n    # contains them, so the pull-back is a no-op and the animation simply carries on turning at\\n    # the same size -- which is what \\\"if the 3D models are larger than the EM, then it should zoom\\n    # out\\\" asks for, read the other way round.\\n    ortho_turn = max(ortho_turn, ortho_sweep) if stage_em else ortho_turn\\n\\n    cam_data.ortho_scale = ortho_sweep if stage_em else ortho_turn\\n    view_w = cam_data.ortho_scale\\n    view_h = view_w / aspect\\n\\n    d = span * 2.0 + 1.0\\n    start_centre = em_centre if stage_em else centre\\n    start_elev = 0.0 if stage_em else elev\\n    cam.location, _off, cam.rotation_euler = camera_pose(start_centre, d, start_elev)\\n    scene.camera = cam\\n\\n    # Three suns, not one. A single key light leaves every surface facing away from it black, and\\n    # on a translucent cell \\\"black\\\" and \\\"empty space\\\" look identical -- the fill and rim are what\\n    # let you tell a membrane curving away from you from a hole in it.\\n    # Energies are for the STANDARD view transform set below, not for AgX: without a filmic\\n    # shoulder to roll them off, photographic levels clip the membranes to white.\\n    #\\n    # AIMED BY DIRECTION, not by Euler angles. The previous version wrote the three lamps as\\n    # hand-typed rotations -- Key (50, 0, 35), Fill (65, 0, 200), Rim (115, 0, 300) -- and two of\\n    # the three were pointing somewhere useless. Working them out: a sun shines down its own local\\n    # -Z, so (65, 0, 200) travels towards (0.31, -0.85, -0.42), i.e. AWAY from the camera, lighting\\n    # the far side of everything; and (115, 0, 300) travels towards (0.79, 0.45, +0.42), which is\\n    # partly UPWARDS, so most of it lit nothing at all. Only the key was doing any work, which is\\n    # half the reason a real cell came out as a contour.\\n    #\\n    # So the lamps are now given as the direction each one SHINES IN, in the camera's own frame:\\n    # the camera sits at -Y and looks towards +Y, so a light that travels with +Y front-lights the\\n    # scene and one that travels with -Y back-lights it. to_track_quat turns each into a rotation,\\n    # which removes the class of mistake entirely -- there is no angle left to get wrong.\\n    #\\n    #   Key    down and to the right, from over the viewer's left shoulder -- the modelling light\\n    #   Fill   up and to the left, still from the front -- opens the shadow side without flattening\\n    #   Rim    from behind and above, towards the camera -- separates a membrane from the\\n    #          background at its silhouette, which on a neurite is nearly all of it\\n    #\\n    # Energies roughly tripled at the same time. The old numbers were set on synthetic blobs at\\n    # alpha 0.25, where a fifth of a lit surface still reads; against uJump's near-black background\\n    # with real, thin geometry they did not. Nothing clips: checked on the rendered preview, whose\\n    # brightest membrane pixel stays under 250.\\n    for nm, energy, shine in ((\\\"Key\\\", 6.5, (0.45, 0.80, -0.40)),\\n                              (\\\"Fill\\\", 3.0, (-0.55, 0.70, 0.45)),\\n                              (\\\"Rim\\\", 4.5, (0.10, -0.75, -0.65))):\\n        ld = bpy.data.lights.new(nm, type=\\\"SUN\\\")\\n        ld.energy = energy\\n        ld.angle = math.radians(15)          # soft shadow terminator on a curved membrane\\n        ob = bpy.data.objects.new(nm, ld)\\n        ob.location = tuple(centre + np.array([d, -d, d]))\\n        # to_track_quat's argument is the direction the named axis is to END UP pointing along,\\n        # so the SHINE direction goes in directly. The first version passed -v -- which aimed\\n        # every lamp backwards and left exactly one of the three front-lighting anything. The\\n        # framing check caught it; that is why it counts lamps by their world direction rather\\n        # than trusting the numbers in this table.\\n        v = mathutils.Vector(shine)\\n        v.normalize()\\n        ob.rotation_euler = v.to_track_quat(\\\"-Z\\\", \\\"Y\\\").to_euler()\\n        scene.collection.objects.link(ob)\\n\\n    # \u2500\u2500 the headlight \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # S\u00f8ren, on a real export: \\\"It seems like the light is turned off when I do the rendering\\\" --\\n    # a nucleus rendered as a flat black silhouette against its own EM section.\\n    #\\n    # The three suns above are a lighting DESIGN: key, fill and rim, fixed in world space so the\\n    # turntable reveals form as it turns. What they cannot promise is that the surface facing the\\n    # camera is lit at all -- that depends on where the geometry is, what is between it and each\\n    # sun, and which way it faces. On synthetic cells it always worked; on a real one it did not,\\n    # and chasing which of those three it was is worth less than making the question moot.\\n    #\\n    # So: a fourth sun, PARENTED TO THE CAMERA and pointing straight down the lens. Whatever is in\\n    # the way of the other three, what you are looking at is lit. Energy is deliberately low --\\n    # this is a floor, not the key light, and a headlight strong enough to matter flattens every\\n    # form the rim light exists to show.\\n    head_d = bpy.data.lights.new(\\\"Headlight\\\", type=\\\"SUN\\\")\\n    head_d.energy = 3.0                       # was 1.1, and 1.1 was not enough to see\\n    head_d.angle = math.radians(25)\\n    head = bpy.data.objects.new(\\\"Headlight\\\", head_d)\\n    scene.collection.objects.link(head)\\n    head.parent = cam\\n    head.location = (0.0, 0.0, 0.0)\\n    head.rotation_euler = (0.0, 0.0, 0.0)   # a sun points along its own -Z; so does a camera\\n\\n    world = bpy.data.worlds.new(\\\"World\\\")\\n    world.use_nodes = True\\n    bg = world.node_tree.nodes.get(\\\"Background\\\")\\n    if bg:\\n        add_ambient_floor(world, bg)\\n        # S\u00f8ren, twice: \\\"the background should be dark\\\" and then \\\"I meant the same dark blue\\n        # background ... what is used for the dark version of \u00b5Jump\\\". So it is not a colour picked\\n        # to look right -- it is \u00b5Jump's own --bg, #0d1117, read off the :root rule in ujump.html\\n        # and converted sRGB -> linear like every other colour here. A render and the tool now sit\\n        # on the same ground, which is the point.\\n        bg.inputs[0].default_value = hex_rgba(UJUMP_BG, 1.0)\\n        bg.inputs[1].default_value = 1.0\\n    scene.world = world\\n\\n    # \u2500\u2500 the view transform, which is why the first attempt at this looked black \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # Setting the world to \u00b5Jump's #0d1117 and rendering it produced a near-black frame. The colour\\n    # was right; AgX was in the way. Blender's default view transform is a filmic curve built for\\n    # photographic realism -- it darkens the low end and desaturates, so #0d1117 arrives as almost\\n    # nothing and the palette's #8a3b2a arrives as something other than #8a3b2a.\\n    #\\n    # 'Standard' is a straight linear->sRGB encode: what is specified is what is rendered. For a\\n    # figure whose entire job is that its colours match the tool the reader was just looking at,\\n    # that is the correct choice rather than the pretty one. It also means the cell colours in a\\n    # render are the same hex values as the bars in \u00b5Jump's own charts.\\n    scene.view_settings.view_transform = \\\"Standard\\\"\\n    scene.view_settings.look = \\\"None\\\"\\n\\n    # \u2500\u2500 the viewport the file opens with \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # See UNITS AND CLIPPING. Without this the .blend opens on an empty-looking viewport because\\n    # every object sits beyond the default 100-unit far plane.\\n    scene.cursor.location = tuple(centre)\\n    n_views = 0\\n    for screen in bpy.data.screens:\\n        for area in screen.areas:\\n            if area.type != \\\"VIEW_3D\\\":\\n                continue\\n            for space in area.spaces:\\n                if space.type != \\\"VIEW_3D\\\":\\n                    continue\\n                space.clip_start = 0.01\\n                space.clip_end = max(span * 40.0, 2000.0)\\n                if getattr(space, \\\"region_3d\\\", None):\\n                    space.region_3d.view_location = tuple(centre)\\n                    space.region_3d.view_distance = span * 1.6 + 1.0\\n                    # \u2500\u2500 THE FILE OPENS LOOKING THROUGH THE CAMERA \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n                    # S\u00f8ren, five times, ending with a contact sheet he had rendered himself:\\n                    # \\\"It did not work although the preview looks like it worked.\\\"\\n                    #\\n                    # That sentence is the whole diagnosis. The preview and the video come out of\\n                    # the same renderer, through the same camera, so a preview that is right means\\n                    # the FILE is right -- and what is being watched is therefore not the camera.\\n                    # It is the 3D viewport, which is a free view of the scene and has nothing to\\n                    # do with the shot. In the viewport the pan is obvious (the camera object\\n                    # slides across the screen) and the zoom is INVISIBLE, because zoom is a\\n                    # property of the lens, not a movement of anything. That is exactly the report,\\n                    # every time: it pans, it does not zoom, and most of the cell is out of view.\\n                    #\\n                    # Telling him to press Numpad 0 did not fix it, and after four rounds that is\\n                    # my problem to solve, not his to remember. So the saved file opens in camera\\n                    # view. Press play and you are watching the shot. Numpad 0 leaves it.\\n                    space.region_3d.view_perspective = \\\"CAMERA\\\"\\n                if getattr(space, \\\"shading\\\", None):\\n                    space.shading.type = \\\"MATERIAL\\\"      # so the transparency is visible on open\\n                n_views += 1\\n\\n    # \u2500\u2500 press play \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    # What the animation IS depends on what the box was asked to include, and every combination\\n    # has to make sense on its own:\\n    #\\n    #   EM + 3D models    sweep face-on through the sections with the cells in place throughout,\\n    #                     pull back, then turn\\n    #   3D models only    turn. (\\\"If the EM is not included, then the animation should just\\n    #                     rotate around the cells.\\\")\\n    #   EM only           sweep, and stop. (\\\"If the mesh is not included, then it should just\\n    #                     scroll through the EM.\\\") Nothing to rotate around; a turntable about an\\n    #                     empty box is a rotating rectangle.\\n    bar_len, bar, lab = add_scale_bar(scene, cam, view_w, view_h)\\n    bar_wide = None\\n    zoom_end = em_frames\\n\\n    # THE SECTIONS GO AS THE CAMERA STARTS TO MOVE. S\u00f8ren: \\\"the EM should disappear when starting\\n    # the zooming out and rotation.\\\" An earlier version kept the plane through the pull-back so\\n    # the imagery shrank into the wider framing; he has seen both and prefers the clean break, and\\n    # he is right that the two things reading as one move is confusing -- the sweep is over, so\\n    # the sweep's subject should leave.\\n    em_ob = bpy.data.objects.get(\\\"EM_sections\\\")\\n    if em_ob is not None and em_frames:\\n        key_hide(em_ob, [(1, False), (em_frames + 1, True)])\\n\\n    if has_geo and stage_em:\\n        pivot = add_turntable(scene, cam, centre, TURNTABLE_FRAMES, FPS,\\n                              start_frame=em_frames + ZOOM_FRAMES)\\n        zoom_end = add_pull_back(cam, pivot, em_centre, centre, d, elev,\\n                                 ortho_sweep, ortho_turn, em_frames, ZOOM_FRAMES)\\n        if ortho_turn > ortho_sweep * 1.001:\\n            # \u2500\u2500 A SECOND CAMERA FOR THE REVOLUTION \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n            # S\u00f8ren, four times now: \\\"it does not zoom out while panning to the center of the\\n            # figure before rotating, so most of the figure is not visible in the rotation.\\\" And,\\n            # this time: \\\"I just want either the camera to move backwards or the camera to be\\n            # larger.\\\"\\n            #\\n            # Neither of those does anything, and that is worth writing down rather than\\n            # re-deriving. Under ORTHOGRAPHIC projection distance has no effect on size at all --\\n            # that is the definition of the projection -- so moving the camera back is a no-op.\\n            # And a camera object's SCALE is ignored by the render: measured, not assumed, on a\\n            # 5 um plane, which covers 0.250 of the frame at camera scale 1 and 0.250 at camera\\n            # scale 2. The single lever an orthographic camera has is ortho_scale, and ortho_scale\\n            # lives on the camera DATA, not on the object.\\n            #\\n            # add_pull_back animates exactly that, and it is verified: the saved .blend is\\n            # re-opened, stepped, and read back widening. It has never reproduced here. So rather\\n            # than defend the animation again, the REVOLUTION -- the part he says is unusable --\\n            # is handed to its own camera whose ortho_scale is a plain static number with no\\n            # animation on it anywhere.\\n            #\\n            #   Camera        the sweep and the pull-back. ortho_scale animated, as before.\\n            #   Camera_turn   from the first turntable frame on. ortho_scale = ortho_turn, static.\\n            #\\n            # A timeline marker binds the second camera from `zoom_end`. Markers are scene data,\\n            # so the switch cannot fail the way an animated property on a camera datablock might.\\n            # If the pull-back animates, the two land on the same number and the cut is invisible;\\n            # if it somehow does not, the rotation is STILL framed on the whole cell set, which is\\n            # the thing that actually matters.\\n            turn_data = bpy.data.cameras.new(\\\"Camera_turn\\\")\\n            turn_data.type = \\\"ORTHO\\\"\\n            turn_data.clip_start, turn_data.clip_end = cam_data.clip_start, cam_data.clip_end\\n            turn_data.ortho_scale = ortho_turn\\n            cam_turn = bpy.data.objects.new(\\\"Camera_turn\\\", turn_data)\\n            scene.collection.objects.link(cam_turn)\\n            _tl, t_off, t_rot = camera_pose(centre, d, elev)\\n            cam_turn.parent = pivot          # rides the same revolution\\n            cam_turn.location = t_off\\n            cam_turn.rotation_euler = t_rot\\n            m1 = scene.timeline_markers.new(\\\"sweep\\\", frame=1)\\n            m1.camera = cam\\n            m2 = scene.timeline_markers.new(\\\"turntable\\\", frame=zoom_end)\\n            m2.camera = cam_turn\\n\\n            # THE SCALE BAR CANNOT SIMPLY RIDE THROUGH THE ZOOM. Its length is a world distance,\\n            # so it stays honest; but it is placed in the corner of a frame whose size changes,\\n            # and a bar sized for one view is either off-screen or absurd in the other. Two bars,\\n            # one per act, and neither is shown during the second the frame is changing size.\\n            # The wide one hangs off the TURNTABLE camera, so it is in that camera's corner.\\n            bar_wide, b2, l2 = add_scale_bar(scene, cam_turn, ortho_turn, ortho_turn / aspect,\\n                                             suffix=\\\"_wide\\\")\\n            for ob in (bar, lab):\\n                key_hide(ob, [(1, False), (em_frames + 1, True)])\\n            for ob in (b2, l2):\\n                key_hide(ob, [(1, True), (zoom_end, False)])\\n        else:\\n            # NOT A FAULT, and it used to be silent. If the cells are smaller than the EM box the\\n            # sweep framing already contains them, so there is nothing to pull back from -- see\\n            # \\\"Never zoom IN to rotate\\\" above. Said out loud, because \\\"it does not zoom out\\\" and\\n            # \\\"it did not need to\\\" look identical from the outside.\\n            print(\\\"%-22s %s\\\"\\n                  % (\\\"no pull-back needed\\\", \\\"the 3D models (%.0f um across) already fit the \\\"\\n                     \\\"sweep framing (%.0f um), so the camera holds one size throughout\\\"\\n                     % (math.hypot(float(ext[0]), float(ext[1])), ortho_sweep)))\\n    elif has_geo:\\n        add_turntable(scene, cam, centre, TURNTABLE_FRAMES, FPS, start_frame=em_frames + 1)\\n    else:\\n        scene.frame_start, scene.frame_current = 1, 1\\n        scene.frame_end = max(em_frames, 1)\\n        scene.render.fps = FPS\\n\\n    total_frames = scene.frame_end\\n    video_path = set_video_output(scene, out_blend, total_frames, FPS,\\n                                  suffix=\\\"_turntable\\\" if has_geo and not em_frames\\n                                  else (\\\"_sweep\\\" if em_frames and not has_geo else \\\"_animation\\\"))\\n    scene.frame_end = total_frames\\n\\n    # A record of where this came from, readable in Blender's own custom-properties panel.\\n    scene[\\\"source\\\"] = man.get(\\\"source\\\", \\\"\\\")\\n    scene[\\\"dataset\\\"] = man.get(\\\"dataset\\\", \\\"\\\")\\n    scene[\\\"units\\\"] = \\\"micrometres (1 Blender unit = 1 um)\\\"\\n    scene[\\\"frame\\\"] = frame\\n    scene[\\\"frame_note\\\"] = (\\\"dataset (x,y,z) -> Blender (x,-z,-y), the same orientation uJump's own \\\"\\n                           \\\".glb export opens in\\\" if frame == \\\"microns\\\"\\n                           else \\\"as supplied, no axis change\\\")\\n    scene[\\\"bbox_um\\\"] = [float(x) for x in list(lo) + list(hi)]\\n    scene[\\\"written_by_blender\\\"] = bpy.app.version_string\\n\\n    # Would the camera actually see the cells? The first version of the framing above pointed at\\n    # empty space and rendered a picture of the world background -- which looks like a perfectly\\n    # successful run unless somebody opens the file. Cheap to check, so it is checked.\\n    from bpy_extras.object_utils import world_to_camera_view\\n    # AT THE TURNTABLE FRAME, not frame 1. During the sweep the camera is deliberately zoomed to\\n    # the EM box, so geometry larger than the box is legitimately outside the frame and checking\\n    # there would report a fault every time. What must hold is that the pull-back arrives\\n    # somewhere the whole set is visible.\\n    scene.frame_set(total_frames if has_geo else 1)\\n    # matrix_world is stale until the depsgraph catches up with the rotation just assigned --\\n    # without this every corner projects from an identity matrix and the check cries wolf.\\n    bpy.context.view_layer.update()\\n    corners = [mathutils.Vector((x, y, z)) for x in (lo[0], hi[0])\\n               for y in (lo[1], hi[1]) for z in (lo[2], hi[2])]\\n    shot = active_camera(scene, scene.frame_current)\\n    seen = [world_to_camera_view(scene, shot, c) for c in corners]\\n    in_view = sum(1 for p in seen if 0.0 <= p.x <= 1.0 and 0.0 <= p.y <= 1.0 and p.z > 0)\\n    # PRINTED EVERY TIME, not only on failure. \\\"It does not zoom out far enough\\\" is a report that\\n    # cannot be acted on without knowing what the file actually did, and the one line that settles\\n    # it costs nothing to print. 8/8 corners of the geometry's bounding box means every vertex is\\n    # in frame, because the box contains the mesh.\\n    print(\\\"%-22s %d/8 bounding-box corners in frame at the turntable, ortho %.0f um for a \\\"\\n          \\\"%.0f x %.0f x %.0f um set\\\"\\n          % (\\\"framing\\\", in_view, shot.data.ortho_scale, ext[0], ext[1], ext[2]))\\n    if in_view < len(corners):\\n        print(\\\"  ! the camera does not hold the whole set. Please report this line.\\\")\\n    scene.frame_set(1)\\n\\n    # THE EM SLICES CANNOT BE PACKED INTO THE .blend. Tried it: bpy.ops.file.pack_all() answers\\n    #     \\\"Image 'em_0001.png' skipped, packing movies or image sequences not supported\\\"\\n    # and packs nothing. Blender keeps image SEQUENCES external by design. So a scene with an EM\\n    # sweep is a .blend PLUS its em/ folder, and whatever ships it has to ship both -- the Colab\\n    # notebook zips them together. Sent as a lone .blend it opens with every section magenta,\\n    # which looks like a broken file rather than a missing folder.\\n    if em_frames:\\n        print(\\\"%-22s %s  (an image sequence cannot be packed; ship the folder with the .blend)\\\"\\n              % (\\\"EM slices stay in\\\", os.path.join(base, os.path.dirname(em[\\\"slices\\\"]))))\\n\\n    bpy.ops.wm.save_as_mainfile(filepath=os.path.abspath(out_blend))\\n\\n\\n    # WHICH BLENDER WROTE THIS, printed because the first delivered test scene could not be\\n    # opened at all. It was built with bpy 5.0.1, whose files carry the new large-pointer header\\n    # (\\\"BLENDER17-01v0500\\\"); every Blender before 5.0 reads that, fails the 12-byte magic check\\n    # and reports \\\"not a blend file\\\" -- which sounds like a corrupt download and is not. Blender\\n    # opens files from older versions, never from newer ones, so build with the OLDEST version\\n    # you need to support: a 4.2 file opens in 4.2 through 5.x.\\n    print(\\\"\\\\n%-22s %s\\\" % (\\\"written by\\\", \\\"Blender \\\" + bpy.app.version_string))\\n    print(\\\"%-22s %s\\\" % (\\\"dataset\\\", man.get(\\\"dataset\\\", \\\"\\\")))\\n    print(\\\"%-22s %d\\\" % (\\\"cells\\\", n_cells))\\n    if n_vasc_v:\\n        print(\\\"%-22s %s vertices  (Wan & Wei 2024 TriSAM, cut to the box, alpha %.2f)\\\"\\n              % (\\\"vasculature\\\", format(n_vasc_v, \\\",\\\"), float(vasc.get(\\\"alpha\\\", 0.30))))\\n    print(\\\"%-22s %d\\\" % (\\\"nuclei\\\", n_nuclei))\\n    print(\\\"%-22s %s\\\" % (\\\"vertices\\\", format(total_v, \\\",\\\")))\\n    print(\\\"%-22s %.0f x %.0f x %.0f um\\\" % tuple([\\\"extent\\\"] + list(hi - lo)))\\n    print(\\\"%-22s %.0f, %.0f, %.0f um (absolute)\\\" % tuple([\\\"centre\\\"] + list(centre)))\\n    print(\\\"%-22s %d, and every one of them OPENS IN CAMERA VIEW -- press Space to play the shot; \\\"\\n          \\\"Numpad 0 leaves the camera for a free view\\\" % (\\\"viewports fixed\\\", n_views))\\n    if n_cells:\\n        print(\\\"%-22s %s\\\" % (\\\"cells are\\\", \\\"translucent (alpha %.2f), nuclei opaque\\\" % cell_alpha\\n                            if cell_alpha < 1.0 else \\\"opaque -- no nuclei in this export\\\"))\\n    if em_frames:\\n        half = act_two - 1\\n        print(\\\"%-22s %d sections, frames 1-%d (%.1f s), back to front, no 3D models%s\\\"\\n              % (\\\"act 0: EM sweep out\\\", half + 1, act_two, act_two / float(FPS),\\n                 \\\", face-on\\\" if stage_em else \\\"\\\"))\\n        print(\\\"%-22s frames %d-%d (%.1f s), front to back, 3D models present\\\"\\n              % (\\\"act 1: EM sweep back\\\", act_two, em_frames,\\n                 (em_frames - act_two + 1) / float(FPS)))\\n    if has_geo and em_frames and stage_em:\\n        print(\\\"%-22s frames %d-%d, ortho %.0f -> %.0f um\\\"\\n              % (\\\"pull back\\\", em_frames + 1, zoom_end, ortho_sweep, ortho_turn))\\n    if has_geo:\\n        print(\\\"%-22s frames %d-%d, %d frames at %d fps = %.0f s, one full revolution\\\"\\n              % (\\\"turntable\\\", zoom_end if stage_em and em_frames else em_frames + 1,\\n                 total_frames, TURNTABLE_FRAMES, FPS, TURNTABLE_FRAMES / float(FPS)))\\n    else:\\n        print(\\\"%-22s %s\\\" % (\\\"turntable\\\", \\\"none -- no 3D models in this export\\\"))\\n    print(\\\"%-22s %g um%s  (orthographic, so it is true everywhere in frame)\\\"\\n          % (\\\"scale bar\\\", bar_len, (\\\" during the sweep, %g um after\\\" % bar_wide) if bar_wide\\n             else \\\"\\\"))\\n    print(\\\"%-22s %s  (Ctrl+F12 in Blender)\\\" % (\\\"video\\\", video_path))\\n    if missing:\\n        print(\\\"%-22s %d  (%s%s)\\\" % (\\\"missing meshes\\\", len(missing), \\\", \\\".join(missing[:4]),\\n                                    \\\", ...\\\" if len(missing) > 4 else \\\"\\\"))\\n    # THE ZOOM'S OWN ACTION, printed because sharing it with the camera object is what broke the\\n    # pull-back for four deliveries and left no error behind. See the note at cam_data's creation.\\n    if has_geo and em_frames and stage_em:\\n        oa = cam.animation_data.action if cam.animation_data else None\\n        da = cam.data.animation_data.action if cam.data.animation_data else None\\n        print(\\\"%-22s %s  (object action %s, lens action %s)\\\"\\n              % (\\\"zoom animation\\\",\\n                 \\\"on its own action\\\" if (da is not None and da is not oa)\\n                 else \\\"*** SHARED WITH THE CAMERA OBJECT -- the zoom will not survive re-opening; \\\"\\n                      \\\"please report this line ***\\\",\\n                 oa.name if oa else \\\"none\\\", da.name if da else \\\"none\\\"))\\n    print(\\\"%-22s %s\\\" % (\\\"wrote\\\", os.path.abspath(out_blend)))\\n\\n    if preview_png:\\n        # A STILL, so the format has to be forced back off FFMPEG -- set_video_output() left the\\n        # scene configured to write an MP4, and render(write_still=True) would obediently produce\\n        # a one-frame video named preview.png. Restored afterwards so the saved .blend is still\\n        # set up for Ctrl+F12; the file was written before this block, so the change is local.\\n        #\\n        # FOUR PANELS, not one. See render_contact_sheet's docstring: a single frame cannot show\\n        # whether the camera pulls back, and \\\"it does not zoom out\\\" has now been reported four\\n        # times against a file whose ortho_scale demonstrably widens.\\n        turn_start = zoom_end if (has_geo and stage_em and em_frames) else em_frames + 1\\n        if has_geo and em_frames:\\n            panels = [(1, \\\"the sweep starts, at the back of the box\\\"),\\n                      # MID act one, not the turn itself: at the turn the plane is at the near\\n                      # face of the box, so it stands in front of every model and the panel shows\\n                      # nothing but EM. Half way back it is behind them, which is the shot.\\n                      ((act_two + em_frames) // 2,\\n                       \\\"half way back, 3D models standing out of the tissue\\\"),\\n                      (turn_start, \\\"the pull-back has FINISHED; the turntable starts here\\\"),\\n                      (min(turn_start + TURNTABLE_FRAMES // 3, total_frames),\\n                       \\\"a third of a revolution later\\\")]\\n        elif has_geo:\\n            panels = [(1 + k * TURNTABLE_FRAMES // 4, \\\"%d degrees\\\" % (k * 90)) for k in range(4)]\\n        else:\\n            step = max((em_frames - 1) // 3, 1)\\n            panels = [(min(1 + k * step, em_frames), \\\"section %d\\\" % (1 + k * step))\\n                      for k in range(4)]\\n        try:\\n            path = render_contact_sheet(scene, [p[0] for p in panels], preview_png)\\n            print(\\\"%-22s %s\\\" % (\\\"preview\\\", path))\\n            print(\\\"%-22s %s\\\" % (\\\"\\\", \\\"four panels, left to right then down:\\\"))\\n            for f, what in panels:\\n                scene.frame_set(int(f))\\n                print(\\\"%-22s   frame %-5d ortho %4.0f um  [%s]  %s\\\"\\n                      % (\\\"\\\", f, active_camera(scene, int(f)).data.ortho_scale,\\n                         active_camera(scene, int(f)).name, what))\\n            # THE ONE LINE THAT SETTLES THE ZOOM, printed from the scene itself rather than from\\n            # the values that were asked for. If panel three's ortho is wider than panel one's,\\n            # the pull-back is in the file; anything that then looks un-zoomed is being looked at\\n            # somewhere other than through this camera (Numpad 0 in Blender).\\n            if has_geo and em_frames and stage_em:\\n                scene.frame_set(1)\\n                a1 = active_camera(scene, 1).data.ortho_scale\\n                scene.frame_set(int(turn_start))\\n                a2 = active_camera(scene, int(turn_start)).data.ortho_scale\\n                print(\\\"%-22s %s  (%.0f -> %.0f um, read back off the built scene)\\\"\\n                      % (\\\"pull-back check\\\",\\n                         \\\"the camera DOES widen\\\" if a2 > a1 * 1.001 else\\n                         \\\"*** THE CAMERA DOES NOT WIDEN -- please report this line ***\\\", a1, a2))\\n        except Exception as e:\\n            print(\\\"%-22s could not be rendered (%s)\\\" % (\\\"preview\\\", e))\\n        # THE BACKGROUND IS STILL \u00b5JUMP'S, checked on the rendered pixel rather than on the value\\n        # that was set. Two things could quietly change it: the view transform (AgX turned #0d1117\\n        # into near-black once already) and the ambient floor added for surfaces the lights miss,\\n        # which is separated from the background by a Light Path node an engine could ignore.\\n        # Sampled at the sheet's own bottom-left corner, which is a corner of a rendered panel.\\n        try:\\n            img = bpy.data.images.load(os.path.abspath(preview_png))\\n            px = tuple(int(round(v * 255)) for v in img.pixels[:3])\\n            want = tuple(int(UJUMP_BG.lstrip(\\\"#\\\")[i:i + 2], 16) for i in (0, 2, 4))\\n            print(\\\"%-22s %s  (uJump's %s is %s)\\\"\\n                  % (\\\"background\\\", \\\"as specified\\\" if max(abs(a - b) for a, b in zip(px, want)) <= 1\\n                     else \\\"*** WRONG: %s ***\\\" % (px,), UJUMP_BG, want))\\n            bpy.data.images.remove(img)\\n        except Exception as e:\\n            print(\\\"%-22s could not be read back (%s)\\\" % (\\\"background\\\", e))\\n        scene.frame_set(1)\\n\\n    return {\\\"cells\\\": n_cells, \\\"nuclei\\\": n_nuclei, \\\"vasculature_vertices\\\": n_vasc_v,\\n            \\\"vertices\\\": total_v,\\n            \\\"extent_um\\\": list(hi - lo), \\\"missing\\\": missing}\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    a = argv_after_dashes()\\n    if not a:\\n        sys.exit(\\\"usage: blender --background --python blend_scene.py -- \\\"\\n                 \\\"manifest.json out.blend [preview.png]\\\")\\n    build(a[0], a[1] if len(a) > 1 else \\\"scene.blend\\\", a[2] if len(a) > 2 else None)\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"%%writefile /content/em_plan.py\\n\\\"\\\"\\\"Decide which EM mip, and how many sections, a bounding box can afford.        2026-09-06\\n\\nS\u00f8ren, after the first Colab run: \\\"for the downloaded Blender file via Co-lab, there was no EM\\ndata, but I guess that area was also way too large. We should set a restriction to how large the\\nvolume can be for downloading EM data.\\\"\\n\\nThe area was not the reason -- v2 of the notebook had no EM step at all, so there was nothing to\\nbe too large. But the restriction he asks for is the right thing to build, because a box that IS\\ntoo large is a real and easy mistake to make: at MICrONS' native 8 nm a 200 um square is 25 000\\npixels across, and asking for it politely gets you a Colab session that fetches for an hour and\\nthen dies.\\n\\nSo: this module takes a box and the source's OWN scale list and answers, before anything is\\ndownloaded, \\\"which mip, how many sections, how many megabytes\\\" -- or refuses and says by how much\\nthe box has to shrink. It is pure arithmetic on the info file, so it is testable without network\\n(emplancheck.py runs it against the real minnie65 EM scales) and the notebook embeds it verbatim.\\n\\n\u2500\u2500 WHAT THE REAL SCALES LOOK LIKE, AND WHY IT MATTERS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nminnie65 EM, read from its info file on 2026-09-06:\\n\\n    mip 0   8 x 8 x 40        212992 x 180224 x 13088\\n    mip 1  16 x 16 x 40\\n    mip 2  32 x 32 x 40\\n    mip 3  64 x 64 x 80        <- z starts halving here too\\n    mip 4 128 x 128 x 160\\n    mip 5 256 x 256 x 320\\n    ...  up to 8192 x 8192 x 10240\\n\\nThe thing worth noticing is that Z downsamples from mip 3 onward. That is lucky: a coarser mip\\ncosts 8x less rather than 4x, and the section count falls with it, so a box that is refused at one\\nmip usually fits comfortably one step up without any striding at all. It also means a \\\"section\\\"\\nin the animation is a real averaged slab of tissue, not one 40 nm section -- worth saying out\\nloud, because a neuroscientist will reasonably assume the latter.\\n\\nVOXEL OFFSETS ARE NOT ZERO (13824, 13824, 14816 at mip 0) and they scale with the mip so that\\noffset * resolution is the same physical nanometre in every scale. Physical nm therefore converts\\nto a voxel index by plain division, and the offset only matters for clamping to the volume's real\\nextent -- which this does, so a box half outside the data comes back as the half that exists\\nrather than as a wall of fill_missing black.\\n\\\"\\\"\\\"\\nimport math\\n\\n\\nclass TooBig(Exception):\\n    \\\"\\\"\\\"Raised when no available mip brings the box under the caps. Carries a human sentence.\\\"\\\"\\\"\\n\\n\\ndef plan_em_cutout(scales, box_um, max_px=1024, max_sections=120, max_mb=250):\\n    \\\"\\\"\\\"scales: the precomputed info file's own \\\"scales\\\" list (cv.info['scales']).\\n    box_um:  ((x0, y0, z0), (x1, y1, z1)) in DATASET micrometres -- the same frame the meshes\\n             are in, because cloud-volume reports mesh vertices in nanometres of this same grid.\\n\\n    Returns a dict describing exactly what to fetch, including the origin_um/size_um that the\\n    scene manifest needs, computed from the ROUNDED, CLAMPED voxel box rather than from the box\\n    that was asked for -- so the textured plane lands on the imagery instead of near it.\\n\\n    The search runs finest-to-coarsest and takes the first mip that satisfies BOTH caps, so the\\n    result is the most detail the caps allow rather than a fixed guess.\\n    \\\"\\\"\\\"\\n    (x0u, y0u, z0u), (x1u, y1u, z1u) = box_um\\n    lo_nm = [min(x0u, x1u) * 1000.0, min(y0u, y1u) * 1000.0, min(z0u, z1u) * 1000.0]\\n    hi_nm = [max(x0u, x1u) * 1000.0, max(y0u, y1u) * 1000.0, max(z0u, z1u) * 1000.0]\\n\\n    tried = []\\n    for mip, sc in enumerate(scales):\\n        res = [float(r) for r in sc[\\\"resolution\\\"]]\\n        off = [int(v) for v in sc.get(\\\"voxel_offset\\\", [0, 0, 0])]\\n        siz = [int(v) for v in sc[\\\"size\\\"]]\\n\\n        lo, hi = [], []\\n        for i in range(3):\\n            a = int(math.floor(lo_nm[i] / res[i]))\\n            b = int(math.ceil(hi_nm[i] / res[i]))\\n            a = max(a, off[i])\\n            b = min(b, off[i] + siz[i])\\n            lo.append(a)\\n            hi.append(max(b, a + 1))       # never an empty axis; one voxel is still a picture\\n        nx, ny, nz = (hi[i] - lo[i] for i in range(3))\\n\\n        stride = max(1, int(math.ceil(nz / float(max_sections))))\\n        sections = 1 + (nz - 1) // stride\\n        download_mb = nx * ny * nz / 1e6            # uint8, one channel\\n        written_mb = nx * ny * sections / 1e6       # before PNG compression, so an over-estimate\\n\\n        tried.append((mip, sc.get(\\\"key\\\", \\\"\\\"), nx, ny, nz, download_mb))\\n        if nx > max_px or ny > max_px or download_mb > max_mb:\\n            continue\\n\\n        # The manifest's frame: pixel (0,0) covers voxel `lo`, so the quad spans lo..hi in x and y.\\n        # In z the sections ARE the planes, so the span runs from the first to the last section\\n        # rather than to the far face of the last voxel -- (sections - 1) steps, not `sections`.\\n        return {\\n            \\\"mip\\\": mip,\\n            \\\"key\\\": sc.get(\\\"key\\\", \\\"\\\"),\\n            \\\"resolution_nm\\\": res,\\n            \\\"voxel_lo\\\": lo,\\n            \\\"voxel_hi\\\": hi,\\n            \\\"nx\\\": nx, \\\"ny\\\": ny, \\\"nz\\\": nz,\\n            \\\"stride_z\\\": stride,\\n            \\\"sections\\\": sections,\\n            \\\"download_mb\\\": download_mb,\\n            \\\"written_mb\\\": written_mb,\\n            \\\"origin_um\\\": [lo[0] * res[0] / 1000.0, lo[1] * res[1] / 1000.0,\\n                          lo[2] * res[2] / 1000.0],\\n            \\\"size_um\\\": [nx * res[0] / 1000.0, ny * res[1] / 1000.0,\\n                        (sections - 1) * stride * res[2] / 1000.0],\\n            \\\"section_thickness_nm\\\": res[2] * stride,\\n        }\\n\\n    # Nothing fit. Say by how much, in the units the box was given in, rather than \\\"too large\\\".\\n    m0, k0, nx0, ny0, nz0, mb0 = tried[0]\\n    best = min(tried, key=lambda t: max(t[2], t[3]) / float(max_px))\\n    span = max(hi_nm[0] - lo_nm[0], hi_nm[1] - lo_nm[1]) / 1000.0\\n    # At the coarsest mip on offer, how wide could the box have been?\\n    coarse_res = float(scales[-1][\\\"resolution\\\"][0])\\n    allowed = max_px * coarse_res / 1000.0\\n    raise TooBig(\\n        \\\"no available mip fits this box under the caps (max_px=%d, max_mb=%d).\\\\n\\\"\\n        \\\"  the box is %.0f um across; at mip %d (%s) that is %d x %d x %d voxels = %.0f MB\\\\n\\\"\\n        \\\"  the coarsest mip on offer (%s) still needs %.0f um or less to stay under %d px.\\\\n\\\"\\n        \\\"  shrink the box, or raise EM_MAX_PX / EM_MAX_MB if this runtime really can take it.\\\"\\n        % (max_px, max_mb, span, best[0], best[1], best[2], best[3], best[4], best[5],\\n           scales[-1].get(\\\"key\\\", \\\"\\\"), allowed, max_px))\\n\\n\\ndef _every(n):\\n    if n == 1:\\n        return \\\"every\\\"\\n    suffix = \\\"th\\\" if 11 <= n % 100 <= 13 else {1: \\\"st\\\", 2: \\\"nd\\\", 3: \\\"rd\\\"}.get(n % 10, \\\"th\\\")\\n    return \\\"every %d%s\\\" % (n, suffix)\\n\\n\\ndef describe(plan):\\n    \\\"\\\"\\\"One block of text to print BEFORE downloading anything. The whole point of the module is\\n    that this is readable and appears first.\\\"\\\"\\\"\\n    return (\\n        \\\"  mip %d (%s)  %.0f x %.0f x %.0f nm per voxel\\\\n\\\"\\n        \\\"  box        %.1f x %.1f x %.1f um  (dataset frame)\\\\n\\\"\\n        \\\"  fetch      %d x %d x %d voxels   ~%.0f MB over the wire\\\\n\\\"\\n        \\\"  sections   %d written, %s slice at this mip  (%.0f nm apart)\\\\n\\\"\\n        \\\"  sweep      %.1f s at 24 fps\\\"\\n        % (plan[\\\"mip\\\"], plan[\\\"key\\\"], plan[\\\"resolution_nm\\\"][0], plan[\\\"resolution_nm\\\"][1],\\n           plan[\\\"resolution_nm\\\"][2],\\n           plan[\\\"nx\\\"] * plan[\\\"resolution_nm\\\"][0] / 1000.0,\\n           plan[\\\"ny\\\"] * plan[\\\"resolution_nm\\\"][1] / 1000.0,\\n           plan[\\\"nz\\\"] * plan[\\\"resolution_nm\\\"][2] / 1000.0,\\n           plan[\\\"nx\\\"], plan[\\\"ny\\\"], plan[\\\"nz\\\"], plan[\\\"download_mb\\\"],\\n           plan[\\\"sections\\\"],\\n           _every(plan[\\\"stride_z\\\"]),\\n           plan[\\\"section_thickness_nm\\\"],\\n           plan[\\\"sections\\\"] / 24.0))\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"%%writefile /content/em_fetch.py\\n\\\"\\\"\\\"Turn a cutout plan into the section PNGs the scene sweeps through.              2026-09-07\\n\\nSplit out of the Colab notebook so it can be tested without a network (emfetchcheck.py drives it\\nwith a stub volume). Needs numpy and Pillow; the volumes are passed in, so it never imports\\ncloud-volume and never knows which dataset it is looking at.\\n\\nS\u00f8ren's bounding box has four independent switches -- EM, segmentation, cell 3D models, nuclei --\\nand this file owns two of them:\\n\\n  EM only              grayscale sections, one shared contrast curve\\n  EM + segmentation    the same sections with the matched cells painted over them, which is the\\n                       overlay core/colabexport.js already writes as a TIFF, in PNG and in colour\\n  segmentation only    the matched cells on black. \\\"If only segmentation is included, then it\\n                       should be like for EM\\\" -- same sweep, different pictures\\n  neither              nothing to do; the scene is a turntable\\n\\n\u2500\u2500 THE THREE CONVENTIONS THAT HAVE TO AGREE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\n  cloud-volume returns (x, y, z)\\n  a PNG is (row, column) with row 0 at the top\\n  blend_scene.py's UVs put PNG row 0 at dataset y-min\\n\\nso every plane is transposed on the way out, and section 1 is dataset z-MIN because\\nadd_em_stack plays the sequence in reverse to sweep from the camera outwards. Neither mistake is\\nvisible on real EM -- it still looks exactly like EM upside down -- which is why the check drives\\nthis with a stub whose values rise with x, with y and with z.\\n\\n\u2500\u2500 ONE CONTRAST CURVE FOR THE WHOLE STACK \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nThe intensity histogram is accumulated across every section during the fetch and the stretch\\napplied afterwards from that. Stretching each section by its own percentiles -- the obvious way,\\nand what a per-slice CLAHE would do -- makes the sweep flicker, because a section through a soma\\nand a section through neuropil get different curves and the animation plays them in sequence.\\n\\n\u2500\u2500 SEGMENTATION IS SAMPLED IN PHYSICAL SPACE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nThe segmentation volume has its own scale list and the planner may well choose a different mip\\nfor it than for the EM. Rather than assume a shared voxel grid, each output pixel and section is\\nconverted to nanometres and back into the segmentation's own indices. That is a few lines of\\narithmetic and it is correct whether or not the two volumes happen to line up.\\n\\\"\\\"\\\"\\nimport os\\n\\nimport numpy as np\\nfrom PIL import Image\\n\\n\\ndef _hex_rgb(h):\\n    h = str(h or \\\"#888888\\\").lstrip(\\\"#\\\")\\n    if len(h) == 3:\\n        h = \\\"\\\".join(c * 2 for c in h)\\n    return [int(h[i:i + 2], 16) for i in (0, 2, 4)]\\n\\n\\ndef _label_lookup(label_colors):\\n    \\\"\\\"\\\"Sorted ids and their colours, for a searchsorted lookup rather than one mask per cell.\\n    Root IDs are 64-bit and do not fit a LUT, so this is the practical way to recolour a plane.\\\"\\\"\\\"\\n    ids = np.array(sorted(int(k) for k in label_colors), dtype=np.uint64)\\n    cols = np.array([_hex_rgb(label_colors[int(i)]) for i in ids], dtype=np.float32)\\n    return ids, cols\\n\\n\\ndef _index_map(n_out, lo_out, res_out, lo_seg, n_seg, res_seg):\\n    \\\"\\\"\\\"Output pixel index -> source voxel index, through nanometres. Pixel centres, clamped.\\\"\\\"\\\"\\n    phys = (np.arange(n_out, dtype=np.float64) + lo_out + 0.5) * res_out\\n    idx = np.floor(phys / float(res_seg)).astype(np.int64) - int(lo_seg)\\n    return np.clip(idx, 0, max(n_seg - 1, 0))\\n\\n\\nclass _SlabCache(object):\\n    \\\"\\\"\\\"One contiguous z-slab at a time. The sections are visited in ascending z, so a slab is\\n    fetched once and dropped once, and a volume whose z chunk is 64 is never asked for the same\\n    chunk twice.\\\"\\\"\\\"\\n\\n    def __init__(self, vol, lo, hi, slab):\\n        self.vol, self.lo, self.hi, self.slab = vol, lo, hi, slab\\n        self.z0 = self.z1 = -1\\n        self.blk = None\\n\\n    def plane(self, z):\\n        z = int(min(max(z, self.lo[2]), self.hi[2] - 1))\\n        if not (self.z0 <= z < self.z1):\\n            self.z0 = self.lo[2] + ((z - self.lo[2]) // self.slab) * self.slab\\n            self.z1 = min(self.z0 + self.slab, self.hi[2])\\n            self.blk = np.asarray(self.vol[self.lo[0]:self.hi[0],\\n                                           self.lo[1]:self.hi[1], self.z0:self.z1])\\n            if self.blk.ndim == 4:\\n                self.blk = self.blk[..., 0]\\n        return self.blk[:, :, z - self.z0]\\n\\n\\ndef fetch_sections(plan, out_dir, em_vol=None, seg_vol=None, seg_plan=None,\\n                   label_colors=None, overlay_opacity=0.35, slab=64,\\n                   lo_pct=0.005, hi_pct=0.995, log=print, stats=None):\\n    \\\"\\\"\\\"Write out_dir/em_0001.png .. and return the manifest block blend_scene.py wants.\\n\\n    plan      from em_plan.plan_em_cutout, on whichever volume is driving the sweep\\n    em_vol    a CloudVolume-like object, or None for a segmentation-only sweep\\n    seg_vol   optional; seg_plan must accompany it (the same box, its own grid)\\n    stats     optional dict, filled in with 'painted' -- how many pixels each section got\\n              coloured. The caller needs it to answer \\\"did the overlay actually land on\\n              anything\\\", which the returned manifest deliberately does not carry: the manifest\\n              goes into the scene file and has no business holding diagnostics.\\n    \\\"\\\"\\\"\\n    os.makedirs(out_dir, exist_ok=True)\\n    for f in os.listdir(out_dir):\\n        if f.startswith(\\\"em_\\\") and f.endswith(\\\".png\\\"):\\n            os.remove(os.path.join(out_dir, f))\\n\\n    lo, hi = plan[\\\"voxel_lo\\\"], plan[\\\"voxel_hi\\\"]\\n    stride, res = plan[\\\"stride_z\\\"], plan[\\\"resolution_nm\\\"]\\n    wanted = list(range(lo[2], hi[2], stride))[:plan[\\\"sections\\\"]]\\n    nx, ny = plan[\\\"nx\\\"], plan[\\\"ny\\\"]\\n\\n    # \u2500\u2500 pass one: the grayscale, plus the histogram the curve comes from \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    raw = os.path.join(out_dir, \\\"_raw\\\")\\n    hist = np.zeros(256, dtype=np.int64)\\n    n = 0\\n    if em_vol is not None:\\n        os.makedirs(raw, exist_ok=True)\\n        for z0 in range(lo[2], hi[2], slab):\\n            z1 = min(z0 + slab, hi[2])\\n            want = [z for z in wanted if z0 <= z < z1]\\n            if not want:\\n                continue                      # a slab with nothing wanted in it is never fetched\\n            blk = np.asarray(em_vol[lo[0]:hi[0], lo[1]:hi[1], z0:z1])\\n            if blk.ndim == 4:\\n                blk = blk[..., 0]\\n            for z in want:\\n                a = np.ascontiguousarray(blk[:, :, z - z0].T)   # (y, x); row 0 = dataset y-min\\n                n += 1\\n                np.save(os.path.join(raw, \\\"%04d.npy\\\" % n), a)\\n                hist += np.bincount(a.reshape(-1), minlength=256)\\n            log(\\\"  EM %d/%d sections\\\" % (n, len(wanted)))\\n        cdf = np.cumsum(hist)\\n        tot = int(cdf[-1]) or 1\\n        v_lo = int(np.searchsorted(cdf, tot * lo_pct))\\n        v_hi = max(int(np.searchsorted(cdf, tot * hi_pct)), v_lo + 1)\\n        lut = np.clip((np.arange(256) - v_lo) * 255.0 / (v_hi - v_lo), 0, 255).astype(np.uint8)\\n        log(\\\"  contrast: %d-%d -> 0-255, one curve for all %d sections\\\" % (v_lo, v_hi, n))\\n    else:\\n        n = len(wanted)\\n        lut = None\\n        log(\\\"  no EM: the sections are segmentation on black\\\")\\n\\n    # \u2500\u2500 pass two: colour, overlay, write \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n    cache = ids = cols = None\\n    if seg_vol is not None and seg_plan is not None and label_colors:\\n        ids, cols = _label_lookup(label_colors)\\n        cache = _SlabCache(seg_vol, seg_plan[\\\"voxel_lo\\\"], seg_plan[\\\"voxel_hi\\\"], slab)\\n        sx = _index_map(nx, lo[0], res[0], seg_plan[\\\"voxel_lo\\\"][0], seg_plan[\\\"nx\\\"],\\n                        seg_plan[\\\"resolution_nm\\\"][0])\\n        sy = _index_map(ny, lo[1], res[1], seg_plan[\\\"voxel_lo\\\"][1], seg_plan[\\\"ny\\\"],\\n                        seg_plan[\\\"resolution_nm\\\"][1])\\n\\n    # With no EM underneath there is nothing to see through, and 35% red on black is a dim\\n    # smudge rather than a cell. A segmentation-only sweep paints at full strength.\\n    if em_vol is None:\\n        overlay_opacity = 1.0\\n\\n    painted = 0\\n    per_section = []\\n    for k in range(n):\\n        if lut is not None:\\n            g = lut[np.load(os.path.join(raw, \\\"%04d.npy\\\" % (k + 1)))]\\n        else:\\n            g = np.zeros((ny, nx), dtype=np.uint8)\\n\\n        if cache is None:\\n            per_section.append(0)\\n            Image.fromarray(g, mode=\\\"L\\\").save(os.path.join(out_dir, \\\"em_%04d.png\\\" % (k + 1)))\\n            continue\\n\\n        # This section's physical z, taken back into the segmentation's own grid.\\n        z_nm = (lo[2] + k * stride + 0.5) * res[2]\\n        sz = int(np.floor(z_nm / float(seg_plan[\\\"resolution_nm\\\"][2])))\\n        pl = cache.plane(sz)                                    # (x, y) in the seg's own indices\\n        seg = pl[np.ix_(sx, sy)].T.astype(np.uint64)            # -> (y, x) on the output grid\\n\\n        j = np.clip(np.searchsorted(ids, seg), 0, len(ids) - 1)\\n        hit = (ids[j] == seg)\\n        here = int(hit.sum())\\n        painted += here\\n        per_section.append(here)\\n        base = np.repeat(g[:, :, None], 3, axis=2).astype(np.float32)\\n        over = cols[j]\\n        a = overlay_opacity * hit[:, :, None]\\n        rgb = np.clip(base * (1.0 - a) + over * a, 0, 255).astype(np.uint8)\\n        Image.fromarray(rgb, mode=\\\"RGB\\\").save(os.path.join(out_dir, \\\"em_%04d.png\\\" % (k + 1)))\\n\\n    if lut is not None:\\n        for f in os.listdir(raw):\\n            os.remove(os.path.join(raw, f))\\n        os.rmdir(raw)\\n    if stats is not None:\\n        stats[\\\"painted\\\"] = per_section\\n        stats[\\\"painted_total\\\"] = painted\\n        stats[\\\"sections_with_paint\\\"] = sum(1 for v in per_section if v)\\n    if cache is not None:\\n        log(\\\"  segmentation: %d ids offered, %d of %d sections carry paint, \\\"\\n            \\\"%.2f%% of pixels painted\\\"\\n            % (len(ids), sum(1 for v in per_section if v), n,\\n               100.0 * painted / max(n * nx * ny, 1)))\\n        if not painted:\\n            # Silence here is the failure that wastes a whole run: the sections come back looking\\n            # like plain EM and nothing says why. Name the three things it can be.\\n            log(\\\"  ! NOTHING WAS PAINTED. Either none of these root IDs is inside the box, or \\\"\\n                \\\"the ids do not match this segmentation's materialisation, or the cells are \\\"\\n                \\\"thinner than one voxel at the chosen mip.\\\")\\n\\n    return {\\n        \\\"slices\\\": os.path.basename(out_dir.rstrip(\\\"/\\\")) + \\\"/em_%04d.png\\\",\\n        \\\"first\\\": 1, \\\"count\\\": n,\\n        \\\"origin_um\\\": [round(v, 4) for v in plan[\\\"origin_um\\\"]],\\n        \\\"size_um\\\": [round(plan[\\\"size_um\\\"][0], 4), round(plan[\\\"size_um\\\"][1], 4),\\n                    # From the sections ACTUALLY written, not from the plan: if the fetch stops\\n                    # short the plane must still end on the last real section rather than past it.\\n                    round((n - 1) * stride * res[2] / 1000.0, 4)],\\n    }\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"%%writefile /content/vasc_mesh.py\\n\\\"\\\"\\\"The blood vessels inside the box, as a mesh.                                     2026-09-07\\n\\nS\u00f8ren: \\\"I would like that vasculature to be used in the colab script for the blender file if a\\ncheck box is ticked that includes the vasculature.\\\"\\n\\nThe vasculature is Wan & Wei's TriSAM segmentation of the whole minnie65 volume, published on\\nBossDB (IEEE J. Biomed. Health Inform. 2025, https://doi.org/10.1109/JBHI.2025.3576643, open\\naccess; data at https://bossdb.org/project/wei2024). It is the same asset \u00b5Jump's\\n\\\"Include vasculature segmentation\\\" checkbox puts in the Neuroglancer view.\\n\\n\u2500\u2500 WHY THIS BUILDS A MESH INSTEAD OF DOWNLOADING ONE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nThe cells in this export arrive as ready-made meshes: `cv.mesh.get(root_id)` gives one cell, and a\\ncell is a bounded object. The vasculature is not. It is ONE segment spanning a millimetre of\\ncortex, so \\\"download the mesh for segment 1\\\" means downloading the vessel tree of the entire\\nvolume in order to show the few vessels crossing a 60 \u00b5m box -- and then the scene's bounding box\\nis the whole dataset and the turntable frames a cubic millimetre.\\n\\nSo the vessels are cut out the same way the EM is: a labelled block over the box, and marching\\ncubes on it. Three things follow from that, and all three are wanted rather than tolerated:\\n\\n  the mesh is CLIPPED to the box, so it is the vessels in this scene and nothing else\\n  it lands on the same voxel grid as the EM sections, so a vessel sits where the EM shows it\\n  the resolution is a dial (the mip the planner picks), not whatever the publisher meshed at\\n\\n\u2500\u2500 THE PADDING, WHICH IS NOT COSMETIC \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nA vessel that leaves through the side of the box is cut by the box. Marching cubes over the raw\\nblock leaves that cut OPEN -- a hole where the vessel exits, so the surface is not closed and in\\nBlender you see straight into a hollow tube from certain angles.\\n\\nThe mask is therefore padded with one voxel of empty space on all six sides before the surface is\\nextracted, which puts a wall behind every cut and caps the tube. The vertices are then shifted\\nback by that one voxel so the geometry still lands where the data says. This is one line and\\nhalf an hour of confusion if it is missing.\\n\\n\u2500\u2500 WHAT IT RETURNS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\nverts (N,3) float32 in ABSOLUTE dataset micrometres, faces (M,3) int32 -- the same shape and frame\\nas the cell meshes, so blend_scene.py's own axis handling applies unchanged.\\n\\\"\\\"\\\"\\nimport numpy as np\\n\\n\\ndef _marching_cubes():\\n    \\\"\\\"\\\"scikit-image, imported late and with a sentence about it if it is missing.\\n\\n    Colab has it preinstalled; a bare Python may not, and \\\"ModuleNotFoundError: skimage\\\" three\\n    cells into a notebook is worth one line of explanation.\\\"\\\"\\\"\\n    try:\\n        from skimage.measure import marching_cubes\\n        return marching_cubes\\n    except ImportError:\\n        raise ImportError(\\n            \\\"the vasculature mesh needs scikit-image (skimage.measure.marching_cubes). \\\"\\n            \\\"Colab has it; elsewhere: pip install scikit-image\\\")\\n\\n\\ndef vasc_mesh(plan, vol, ids=None, step=1, log=print, stats=None):\\n    \\\"\\\"\\\"Surface of the labelled voxels in `plan`'s box.\\n\\n    plan   a plan_em_cutout() result over the VASCULATURE's own scale ladder\\n    vol    a cloud-volume CloudVolume opened at plan['mip']\\n    ids    which labels count as vessel. None (the default) means \\\"any non-zero label\\\", which is\\n           right for a dedicated vessel segmentation -- everything in it IS vessel. Pass a list to\\n           restrict it; \u00b5Jump's viewer selects segment 1 and nothing else, so [1] is the\\n           conservative reading if a future materialisation adds other structures.\\n    step   decimation on the marching-cubes grid. 1 is every voxel; 2 quarters the triangle count\\n           in plane at the cost of a visibly blockier surface.\\n    \\\"\\\"\\\"\\n    mc = _marching_cubes()\\n    lo, hi = plan[\\\"voxel_lo\\\"], plan[\\\"voxel_hi\\\"]\\n    res = plan[\\\"resolution_nm\\\"]\\n    sz = plan[\\\"stride_z\\\"]\\n\\n    block = vol[lo[0]:hi[0], lo[1]:hi[1], lo[2]:hi[2]]\\n    block = np.asarray(block)\\n    if block.ndim == 4:\\n        block = block[..., 0]\\n    if sz > 1:\\n        block = block[:, :, ::sz]\\n\\n    if ids:\\n        want = np.zeros(block.shape, dtype=bool)\\n        for i in ids:\\n            want |= (block == int(i))\\n    else:\\n        want = block != 0\\n\\n    n_vox = int(want.sum())\\n    frac = n_vox / float(max(want.size, 1))\\n    log(\\\"  vasculature  %d of %d voxels are vessel (%.1f%% of the box)\\\"\\n        % (n_vox, want.size, 100.0 * frac))\\n    if stats is not None:\\n        stats[\\\"voxels\\\"] = n_vox\\n        stats[\\\"fraction\\\"] = frac\\n    if n_vox == 0:\\n        # SAID OUT LOUD, because an empty mesh and a mesh that failed to download look identical\\n        # in a scene: both are nothing. Three causes, all of them plausible and all of them the\\n        # user's to judge.\\n        log(\\\"  ! NO VESSEL VOXELS IN THIS BOX. Either there is genuinely no vessel here, or the \\\"\\n            \\\"box is outside the vasculature volume's extent, or the label ids asked for \\\"\\n            \\\"(%s) are not the ones this materialisation uses.\\\" % (ids or \\\"any non-zero\\\",))\\n        return None, None\\n\\n    # ONE VOXEL OF EMPTY SPACE ALL ROUND -- see the module docstring. Without it every vessel that\\n    # leaves through a face of the box is an open tube.\\n    padded = np.zeros([d + 2 for d in want.shape], dtype=np.float32)\\n    padded[1:-1, 1:-1, 1:-1] = want\\n\\n    spacing = (res[0] / 1000.0, res[1] / 1000.0, res[2] * sz / 1000.0)\\n    verts, faces, _n, _v = mc(padded, level=0.5, spacing=spacing, step_size=max(1, int(step)))\\n\\n    # Undo the pad (one voxel, in \u00b5m), then move from box-local to absolute dataset \u00b5m.\\n    origin = np.array(plan[\\\"origin_um\\\"], dtype=np.float64)\\n    verts = verts.astype(np.float64) - np.array(spacing, dtype=np.float64)\\n    verts += origin\\n    log(\\\"  vasculature  %s vertices, %s triangles at mip %d (%s), voxel %.0f x %.0f x %.0f nm\\\"\\n        % (format(len(verts), \\\",\\\"), format(len(faces), \\\",\\\"), plan[\\\"mip\\\"], plan[\\\"key\\\"],\\n           res[0], res[1], res[2] * sz))\\n    if stats is not None:\\n        stats[\\\"vertices\\\"] = int(len(verts))\\n        stats[\\\"faces\\\"] = int(len(faces))\\n    return verts.astype(np.float32), np.asarray(faces, dtype=np.int32)\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 4. Fetch the cell 3D models\\n\\nThe cell that answers the size question. For each cell it PROBES the coarsest level first --\\na small, quick fetch -- then predicts what the finer levels would cost and downloads the\\nfinest one that fits the vertex budget.\\n\\nThe prediction matters: MICrONS multi-resolution meshes roughly QUADRUPLE in vertex count per\\nlevel, so fetching level 0 for a large neuron only to find it is far too big and throw it away\\nwould dominate the run. The probe costs a few hundred KB, and the predicted and actual counts\\nare both printed so the assumed ratio can be checked against reality rather than trusted.\\n\\nSkipped entirely when `INCLUDE['cell_3d_model']` is off \u2014 in which case the scene is whatever\\nthe nuclei and the EM make of it.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {\"ujump\": \"meshes\"}, \"outputs\": [], \"source\": \"from cloudvolume import CloudVolume\\n\\nfor c in CELLS: c['cell_npz'] = None\\ncv = CloudVolume(SEG, use_https=True, progress=False)\\n\\ndef as_mesh(res, segid):\\n    \\\"\\\"\\\"cloud-volume returns a Mesh, a list, or a dict keyed by segid depending on version and\\n    source layout. Normalise rather than assume \u2014 the most likely thing to break on a future\\n    cloud-volume.\\\"\\\"\\\"\\n    if res is None: return None\\n    if isinstance(res, dict): res = res.get(int(segid)) or next(iter(res.values()), None)\\n    if isinstance(res, (list, tuple)): res = res[0] if res else None\\n    return res\\n\\ndef mesh_at(rid, lod):\\n    \\\"\\\"\\\"One level of detail, or (None, lod). A source with no LODs answers the lod= call with\\n    a TypeError, and then there is nothing to choose and lod comes back as None.\\\"\\\"\\\"\\n    try:\\n        return as_mesh(cv.mesh.get(rid, lod=lod), rid), lod\\n    except TypeError:\\n        return as_mesh(cv.mesh.get(rid), rid), None\\n    except Exception:\\n        return None, lod\\n\\nCOARSEST = max(LOD_PREFERENCE)\\nLOD_STEP_RATIO = 4.0    # MICrONS multi-res meshes roughly quadruple per finer level\\n_want = [c for c in CELLS if INCLUDE['cell_3d_model']]\\nBUDGET = max(300_000, min(VERTEX_BUDGET, VERTEX_BUDGET_TOTAL // max(len(_want), 1)))\\nif _want:\\n    print(f'vertex budget {BUDGET:,} per cell  ({len(_want)} cells, '\\n          f'{VERTEX_BUDGET_TOTAL:,} shared, {VERTEX_BUDGET:,} per-cell cap)')\\n\\nreport = []\\nfor c in (CELLS if INCLUDE['cell_3d_model'] else []):\\n    rid = int(c['root_id'])\\n    # 1. probe the coarsest level. Small, quick, and it is the only thing that tells us how\\n    #    big this particular cell is before committing to a download.\\n    probe, plod = mesh_at(rid, COARSEST)\\n    if probe is None:\\n        print(f\\\"  {c['type']:<12} {rid}  NO MESH\\\"); c['cell_npz'] = None; continue\\n    if plod is None:\\n        m, lod, note = probe, None, 'single-resolution source'\\n    else:\\n        n0 = len(probe.vertices)\\n        # 2. finest level whose PREDICTED size fits. sorted() is finest-first whatever order\\n        #    LOD_PREFERENCE was written in.\\n        want, est = COARSEST, n0\\n        for lod in sorted(LOD_PREFERENCE):\\n            e = n0 * (LOD_STEP_RATIO ** (COARSEST - lod))\\n            if e <= BUDGET: want, est = lod, e; break\\n        m, lod = (probe, COARSEST) if want == COARSEST else mesh_at(rid, want)\\n        if m is None: m, lod = probe, COARSEST\\n        # 3. and back off if the prediction was optimistic. Bounded by the level count, so\\n        #    this cannot loop.\\n        while lod is not None and lod < COARSEST and len(m.vertices) > BUDGET * 1.5:\\n            m2, l2 = mesh_at(rid, lod + 1)\\n            if m2 is None: break\\n            m, lod = m2, l2\\n        note = f'probe lod {COARSEST} = {n0:,} verts, predicted {est:,.0f} at lod {want}'\\n    v = np.asarray(m.vertices, dtype=np.float32) / 1000.0    # cloud-volume gives nanometres\\n    f = np.asarray(m.faces, dtype=np.int32).reshape(-1, 3)\\n    rel = f'meshes/cell_{rid}.npz'\\n    np.savez_compressed('/content/out/' + rel, verts=v, faces=f)\\n    mb = os.path.getsize('/content/out/' + rel) / 1e6\\n    c['cell_npz'] = rel\\n    ext = v.max(axis=0) - v.min(axis=0)\\n    report.append((c['type'], lod, len(v), len(f), mb))\\n    print(f\\\"  {c['type']:<12} lod {str(lod):<4} {len(v):>9,} verts  {len(f):>9,} tris  \\\"\\n          f'{mb:6.1f} MB  extent {ext[0]:.0f} x {ext[1]:.0f} x {ext[2]:.0f} um')\\n    print(f'    {note}')\\n\\nif report:\\n    tot = sum(r[4] for r in report)\\n    print(f'\\\\n  {len(report)} cells, {tot:.1f} MB on disk, '\\n          f'{sum(r[2] for r in report):,} vertices total')\\n    print(f'  at this rate 50 cells would be about {tot/len(report)*50:.0f} MB')\\nelif not INCLUDE['cell_3d_model']:\\n    print('cell 3D models not included \u2014 skipped')\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 5. Fetch the nuclei\\n\\nThe MICrONS nucleus source publishes its own meshes (`mesh_mip_0_err_40`, the legacy\\nsingle-resolution precomputed format). Tens to a couple of hundred KB each, so every matched\\ncell can have one at essentially no cost.\\n\\nWhether any nucleus reaches the manifest is also what decides the cells' transparency \u2014\\n`blend_scene.py` reads that off the manifest rather than taking a flag, so the file cannot\\nclaim one thing and contain another.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"for c in CELLS: c['nucleus_npz'] = None\\nnucv = CloudVolume(NUC, use_https=True, progress=False)\\n\\nfor c in (CELLS if INCLUDE['nuclei'] else []):\\n    nid = int(c['nucleus_id'])\\n    try:\\n        m = as_mesh(nucv.mesh.get(nid), nid)\\n    except Exception as e:\\n        print(f\\\"  {c['type']:<12} nucleus {nid}  FAILED: {e}\\\"); c['nucleus_npz'] = None; continue\\n    if m is None:\\n        print(f\\\"  {c['type']:<12} nucleus {nid}  no mesh\\\"); c['nucleus_npz'] = None; continue\\n    v = np.asarray(m.vertices, dtype=np.float32) / 1000.0\\n    f = np.asarray(m.faces, dtype=np.int32).reshape(-1, 3)\\n    rel = f'meshes/nuc_{nid}.npz'\\n    np.savez_compressed('/content/out/' + rel, verts=v, faces=f)\\n    c['nucleus_npz'] = rel\\n    c['position_um'] = [round(float(x), 1) for x in v.mean(axis=0)]\\n    ex = v.max(axis=0) - v.min(axis=0)\\n    print(f\\\"  {c['type']:<12} nucleus {nid}  {len(v):>7,} verts  \\\"\\n          f\\\"{os.path.getsize('/content/out/'+rel)/1e3:6.0f} KB  \\\"\\n          f'{ex[0]:.1f} x {ex[1]:.1f} x {ex[2]:.1f} um')\\n\\n# Is each nucleus actually INSIDE its cell? Root IDs change with proofreading, so a stale\\n# pairing is a real failure mode and it is nearly free to catch here rather than in Blender.\\nprint()\\nfor c in CELLS:\\n    if not (c.get('cell_npz') and c.get('nucleus_npz')): continue\\n    cvv = np.load('/content/out/' + c['cell_npz'])['verts']\\n    nvv = np.load('/content/out/' + c['nucleus_npz'])['verts']\\n    lo, hi, ctr = cvv.min(axis=0), cvv.max(axis=0), nvv.mean(axis=0)\\n    inside = bool(np.all(ctr >= lo) and np.all(ctr <= hi))\\n    print(f\\\"  {c['type']:<12} nucleus inside its cell's bounding box: {inside}\\\")\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 6. The section sweep \u2014 plan it before fetching it\\n\\nThe first two acts are the imagery the cells were segmented out of: a plane that walks the\\nsections face-on and filling the frame, out with nothing drawn on them and back with the 3D\\nmodels in place. Then the pull-back, then the turntable.\\n\\n**This is where the size restriction lives.** At MICrONS' native 8 nm a 200 \u00b5m square is 25 000\\npixels across, so a box that is easy to draw is not necessarily a box that can be fetched.\\n`em_plan.py` reads the source's own scale list, walks it finest-to-coarsest, and takes the first\\nlevel where the sections fit `EM_MAX_PX` and the whole fetch fits `EM_MAX_MB` \u2014 then prints the\\nplan **before** a single byte is downloaded, and refuses with a size to shrink to if nothing fits.\\n\\nTwo things about MICrONS' scales are worth knowing when you read the plan:\\n\\n- **Z downsamples too**, from mip 3 (`64\u00d764\u00d780`) onward. So a \\\"section\\\" here is an averaged slab\\n  \u2014 160 nm at mip 4, 640 nm at mip 6 \u2014 not one 40 nm section. That is fine for a sweep and worth\\n  saying out loud.\\n- **A coarser mip costs 8\u00d7 less, not 4\u00d7**, for the same reason. A box refused at one level\\n  usually fits one step up with no striding at all.\\n\\nThe segmentation gets its own plan against its own scale list, and is sampled through\\nnanometres rather than assuming the two volumes share a voxel grid \u2014 they need not, and at\\ndifferent mips they do not.\\n\\nThe box is small on purpose. A 60 \u00b5m box around one soma lands at mip 3\u20134, where you can still\\nsee ultrastructure; fitting the box to all five scattered test cells would land at mip 6 (512\\nnm/px), which sweeps convincingly and shows no ultrastructure at all. Set `EM_BOX_MODE` to try it.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {\"ujump\": \"plan\"}, \"outputs\": [], \"source\": \"# The caps and the box are set in section 1, with the rest of what the panel decides.\\nsys.path.insert(0, '/content')\\nfrom em_plan import plan_em_cutout, describe, TooBig\\nfrom em_fetch import fetch_sections\\nfrom cloudvolume import CloudVolume\\n\\nWANT_SWEEP = INCLUDE['em'] or INCLUDE['segmentation']\\n\\ndef _box():\\n    if EM_BOX_MODE == 'manual':\\n        if not EM_BOX_UM: raise ValueError('EM_BOX_MODE is manual but EM_BOX_UM is None')\\n        return tuple(tuple(float(v) for v in p) for p in EM_BOX_UM)\\n    if EM_BOX_MODE == 'all_cells':\\n        # Every mesh's own extent, padded \u2014 the box the bounding-box panel would draw round\\n        # the whole filter result.\\n        los, his = [], []\\n        for c in CELLS:\\n            for k in ('cell_npz', 'nucleus_npz'):\\n                if not c.get(k): continue\\n                v = np.load('/content/out/' + c[k])['verts']\\n                los.append(v.min(axis=0)); his.append(v.max(axis=0))\\n        if not los: raise ValueError('no geometry to fit a box to')\\n        lo = np.min(np.array(los), axis=0); hi = np.max(np.array(his), axis=0)\\n        return tuple(lo - 5.0), tuple(hi + 5.0)\\n    ctr = next((c['position_um'] for c in CELLS if c.get('position_um')), None)\\n    if ctr is None:\\n        # No nucleus fetched to centre on (nuclei switched off, say) \u2014 fall back to the first\\n        # mesh's own centroid rather than refusing to place a box at all.\\n        for c in CELLS:\\n            if c.get('cell_npz'):\\n                ctr = list(np.load('/content/out/' + c['cell_npz'])['verts'].mean(axis=0)); break\\n    if ctr is None: raise ValueError('nothing fetched to centre a box on; set EM_BOX_UM')\\n    h = [s / 2.0 for s in EM_BOX_SIZE_UM]\\n    return (tuple(ctr[i] - h[i] for i in range(3)), tuple(ctr[i] + h[i] for i in range(3)))\\n\\nEM_PLAN = SEG_PLAN = None\\nEM_VOL = SEG_VOL = None\\nBOX = None\\nif not WANT_SWEEP:\\n    print('neither EM nor segmentation included \u2014 the animation is a turntable')\\nelse:\\n    BOX = _box()\\n    print('box mode %r -> (%.1f, %.1f, %.1f) .. (%.1f, %.1f, %.1f) um\\\\n'\\n          % ((EM_BOX_MODE,) + tuple(BOX[0]) + tuple(BOX[1])))\\n    caps = dict(max_px=EM_MAX_PX, max_sections=EM_MAX_SECTIONS, max_mb=EM_MAX_MB)\\n    if INCLUDE['em']:\\n        try:\\n            v = CloudVolume(EM, use_https=True, mip=0, fill_missing=True, progress=False)\\n            EM_PLAN = plan_em_cutout(v.info['scales'], BOX, **caps)\\n            EM_VOL = CloudVolume(EM, use_https=True, mip=EM_PLAN['mip'],\\n                                 fill_missing=True, progress=False)\\n            print('EM\\\\n' + describe(EM_PLAN))\\n        except TooBig as e:\\n            print('EM REFUSED\\\\n', e)\\n        except Exception as e:\\n            print('EM planning failed:', repr(e))\\n    if INCLUDE['segmentation']:\\n        try:\\n            v = CloudVolume(SEG, use_https=True, mip=0, fill_missing=True, progress=False)\\n            SEG_PLAN = plan_em_cutout(v.info['scales'], BOX, **caps)\\n            SEG_VOL = CloudVolume(SEG, use_https=True, mip=SEG_PLAN['mip'],\\n                                  fill_missing=True, progress=False)\\n            print('\\\\nsegmentation\\\\n' + describe(SEG_PLAN))\\n        except TooBig as e:\\n            print('SEGMENTATION REFUSED\\\\n', e)\\n        except Exception as e:\\n            print('segmentation planning failed:', repr(e))\\n\\n# The sweep is driven by the EM when there is EM, and by the segmentation when there is not.\\nPLAN = EM_PLAN or SEG_PLAN\\n\\n# Say, in one line, whether the overlay is going to happen. The failure this prevents is the\\n# quiet one: sections that come back looking like ordinary EM, with nothing anywhere saying\\n# that segmentation was switched off, refused, or unreachable.\\nif not INCLUDE['segmentation']:\\n    print(\\\"\\\\nOVERLAY: off \u2014 INCLUDE['segmentation'] is False\\\")\\nelif SEG_PLAN is None:\\n    print('\\\\nOVERLAY: NOT AVAILABLE \u2014 segmentation was asked for but has no plan (see the ')\\n    print('         message above). The sections will be plain EM.')\\nelse:\\n    print('\\\\nOVERLAY: on \u2014 %d matched cells will be painted at %.0f%% over the EM'\\n          % (len(CELLS), 100 * OVERLAY_OPACITY))\\n\\nif PLAN:\\n    o, s = PLAN['origin_um'], PLAN['size_um']\\n    print()\\n    for c in CELLS:\\n        p = c.get('position_um')\\n        if not p: continue\\n        print(f\\\"  {c['type']:<12} nucleus inside the box: \\\"\\n              f\\\"{all(o[i] <= p[i] <= o[i] + s[i] for i in range(3))}\\\")\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 7. Fetch the sections\\n\\n`em_fetch.py` does the work; the notebook only hands it the plans and the volumes. Three\\ndetails in there would be invisible until they were wrong, which is why they have a check:\\n\\n- **Row order.** `blend_scene.py` lays the UVs out so PNG row 0 is dataset *y*-min. cloud-volume\\n  hands back `(x, y, z)`, so each section is transposed on the way out. Get this wrong and every\\n  section is upside down, which on EM noise looks completely plausible.\\n- **One contrast curve for the whole stack.** The histogram is accumulated across every section\\n  during the fetch and the stretch applied afterwards. Per-section percentiles \u2014 the obvious way\\n  \u2014 make the sweep flicker, because a section through a soma and one through neuropil get\\n  different curves.\\n- **The overlay is sampled in physical space**, so a segmentation at a different mip still lands\\n  on the right pixels and the right sections.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {\"ujump\": \"fetch\"}, \"outputs\": [], \"source\": \"EM_MANIFEST = None\\nSTATS = {}\\nif not PLAN:\\n    print('no sections \u2014 the animation will be a turntable, starting at frame 1')\\nelse:\\n    label_colors = {int(c['root_id']): COLORS[c['type']] for c in CELLS}\\n    STATS = {}\\n    t0 = time.time()\\n    EM_MANIFEST = fetch_sections(\\n        PLAN, '/content/out/em',\\n        em_vol=EM_VOL,\\n        seg_vol=SEG_VOL, seg_plan=SEG_PLAN,\\n        label_colors=label_colors if SEG_VOL is not None else None,\\n        overlay_opacity=OVERLAY_OPACITY, stats=STATS)\\n    mb = sum(os.path.getsize(f) for f in glob.glob('/content/out/em/*.png')) / 1e6\\n    print(f\\\"  {EM_MANIFEST['count']} sections, {mb:.1f} MB of PNG, {time.time()-t0:.0f}s\\\")\\n    print('  ', EM_MANIFEST)\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"# A look at three sections before anything is rendered \u2014 the cheapest possible check that the\\n# box is where you think it is, that the imagery is not blank, and that the overlay landed.\\n#\\n# When there IS an overlay it shows the three sections carrying the MOST paint, not the first,\\n# middle and last. A cell occupies a few sections out of a hundred, so a fixed sample will\\n# usually miss it and the run looks like it did nothing.\\nif EM_MANIFEST:\\n    from IPython.display import display\\n    from PIL import Image\\n    painted = (STATS or {}).get('painted') or []\\n    if any(painted):\\n        ks = sorted(sorted(range(len(painted)), key=lambda i: -painted[i])[:3])\\n        ks = [k + 1 for k in ks]\\n        print('the three most-painted sections: %s of %d'\\n              % (ks, EM_MANIFEST['count']))\\n    else:\\n        ks = [1, max(1, EM_MANIFEST['count'] // 2), EM_MANIFEST['count']]\\n    ims = [Image.open('/content/out/em/em_%04d.png' % k).convert('RGB') for k in ks]\\n    w = min(300, ims[0].width)\\n    h = int(ims[0].height * w / ims[0].width)\\n    strip = Image.new('RGB', (w * len(ims) + 8 * (len(ims) - 1), h), (0, 0, 0))\\n    for i, im in enumerate(ims):\\n        strip.paste(im.resize((w, h)), (i * (w + 8), 0))\\n    print('sections %s  (section 1 = dataset z-min, i.e. the LAST frame of the sweep)'\\n          % (ks,))\\n    display(strip)\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 7b. Fetch the blood vessels\\n\\nS\u00f8ren: *\\\"I would like that vasculature to be used in the colab script for the blender file if\\na check box is ticked that includes the vasculature.\\\"*\\n\\nWan & Wei's TriSAM segmentation of minnie65, the same asset \u00b5Jump's *Include vasculature\\nsegmentation* checkbox puts in the Neuroglancer view.\\n\\n**It is cut out and surfaced, not downloaded as a mesh.** The vasculature is ONE segment\\nspanning a millimetre of cortex, so `mesh.get(1)` would fetch the vessel tree of the entire\\nvolume to show the few vessels crossing a 60 \u00b5m box -- and the scene's bounding box would then\\nbe the whole dataset. Instead the labels are cut to the same box as the EM and run through\\nmarching cubes (see `vasc_mesh.py`), which clips the vessels to the scene, lands them on the\\nsame grid the sections use, and makes the resolution a dial rather than whatever the publisher\\nmeshed at.\\n\\n**It runs after section 6, not before it, and that is the whole reason this cell is here\\nrather than up beside the cell meshes.** It needs `BOX`, and `BOX` does not exist until the\\nplan cell has built it; placed earlier it died with `NameError: name 'BOX' is not defined`\\nbefore it could say anything useful. Failure here is never fatal either way: the rest of the\\nexport goes on without vessels and says so.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {\"ujump\": \"vasc\"}, \"outputs\": [], \"source\": \"VASC_MESH = None\\nif not INCLUDE['vasculature']:\\n    print('vasculature not included \u2014 skipped')\\nelif BOX is None:\\n    print('vasculature: no bounding box in this export (EM and segmentation are both off), '\\n          'so there is nothing to cut the vessels to \u2014 skipped')\\nelse:\\n    from vasc_mesh import vasc_mesh\\n    try:\\n        _v = CloudVolume(VASC, use_https=True, mip=0, fill_missing=True, progress=False)\\n        VASC_PLAN = plan_em_cutout(_v.info['scales'], BOX,\\n                                   max_px=VASC_MAX_PX, max_sections=VASC_MAX_SECTIONS,\\n                                   max_mb=VASC_MAX_MB)\\n        print('vasculature\\\\n' + describe(VASC_PLAN))\\n        VASC_VOL = CloudVolume(VASC, use_https=True, mip=VASC_PLAN['mip'],\\n                               fill_missing=True, progress=False)\\n        t0 = time.time()\\n        vv, vf = vasc_mesh(VASC_PLAN, VASC_VOL, ids=VASC_IDS, step=VASC_STEP)\\n        if vv is not None:\\n            np.savez_compressed('/content/out/meshes/vasculature.npz', verts=vv, faces=vf)\\n            mb = os.path.getsize('/content/out/meshes/vasculature.npz') / 1e6\\n            VASC_MESH = {'npz': 'meshes/vasculature.npz', 'color': VASC_COLOR,\\n                         'alpha': VASC_ALPHA,\\n                         'source': 'Wan & Wei 2024 TriSAM (BossDB wei2024/minnie/bv)'}\\n            print(f'  {mb:.1f} MB on disk, {time.time()-t0:.0f}s')\\n    except TooBig as e:\\n        print('VASCULATURE REFUSED\\\\n', e)\\n    except Exception as e:\\n        # NOT FATAL, and said in full. The vessels are an extra; an export that dies here\\n        # would cost the whole run over a layer the user can do without.\\n        print('vasculature failed, carrying on without it:', repr(e))\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 8. Write the .glb\\n\\nPure Python. This is the file that always gets written, whatever happens next. It carries the\\ngeometry only \u2014 glTF has nowhere to put an image sequence, so the EM sweep lives in the `.blend`.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"sys.path.insert(0, '/content')\\nfrom glb_write import write_glb\\n\\nobjs = []\\nfor c in CELLS:\\n    col = COLORS[c['type']]\\n    name = f\\\"{c['type'].replace(' ', '_')}_{c['root_id']}\\\"\\n    if c.get('cell_npz'):\\n        z = np.load('/content/out/' + c['cell_npz'])\\n        objs.append({'name': name, 'verts': z['verts'], 'faces': z['faces'],\\n                     'color': col, 'alpha': 0.25})\\n    if c.get('nucleus_npz'):\\n        z = np.load('/content/out/' + c['nucleus_npz'])\\n        objs.append({'name': 'Nucleus_' + name, 'verts': z['verts'], 'faces': z['faces'],\\n                     'color': col, 'alpha': 1.0})\\n\\nif objs:\\n    print(write_glb('/content/out/microns_cells.glb', objs,\\n                    generator='uJump Filter and show -> glTF'))\\nelse:\\n    print('no geometry included \u2014 no .glb. glTF has nowhere to put an image sequence, so '\\n          'an EM-only export is the .blend and its em/ folder.')\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 9. Get Blender \u2014 best effort\\n\\nEverything above is already saved. If this fails, download the `.glb` and stop; you lose the\\nscene setup, not the cells.\\n\\n`urllib`'s default User-Agent gets a **403** from `download.blender.org`, which is what killed\\nthe first run of this notebook \u2014 so every request here sends a browser one, and the exact point\\nrelease is probed rather than guessed.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"UA = {'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 '\\n                    '(KHTML, like Gecko) Chrome/125.0 Safari/537.36'}\\n\\n# BUILD WITH THE OLDEST BLENDER THAT STILL HAS TO OPEN THE RESULT. Blender reads files from\\n# older versions and refuses newer ones \u2014 with 'not a blend file', which reads exactly like a\\n# corrupt download. 4.5 LTS is the floor as of 2026-09: it is the oldest still supported\\n# (4.2 LTS ended July 2026; only 4.5 LTS, to July 2027, and 5.2 LTS remain), and its files\\n# open in 4.5 through 5.2 and later.\\nBLENDER_SERIES = '4.5'\\n\\ndef get(url, timeout=60):\\n    return urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=timeout)\\n\\ndef exists(url):\\n    try:\\n        r = urllib.request.Request(url, headers=UA, method='HEAD')\\n        return urllib.request.urlopen(r, timeout=30).status == 200\\n    except Exception:\\n        return False\\n\\ndef find_blender(series):\\n    \\\"\\\"\\\"Read the point release from the index; if the index refuses, probe for one. Either way\\n    the version is never a hard-coded guess that can 404 mid-run.\\\"\\\"\\\"\\n    base = f'https://download.blender.org/release/Blender{series}/'\\n    try:\\n        idx = get(base).read().decode('utf-8', 'replace')\\n        names = re.findall(rf'blender-({re.escape(series)}\\\\.\\\\d+)-linux-x64\\\\.tar\\\\.xz', idx)\\n        if names:\\n            v = max(names, key=lambda s: int(s.rsplit('.', 1)[1]))\\n            return v, f'{base}blender-{v}-linux-x64.tar.xz'\\n        print('  index listed no linux-x64 build; probing')\\n    except Exception as e:\\n        print(f'  index unreadable ({e}); probing instead')\\n    for n in range(20, -1, -1):\\n        v = f'{series}.{n}'\\n        url = f'{base}blender-{v}-linux-x64.tar.xz'\\n        if exists(url):\\n            return v, url\\n    raise RuntimeError(f'no Blender {series} linux-x64 build found')\\n\\nBLENDER = None\\nfound = glob.glob(f'/content/blender-{BLENDER_SERIES}.*-linux-x64/blender')\\nif found:\\n    BLENDER = found[0]\\nelse:\\n    try:\\n        ver, url = find_blender(BLENDER_SERIES)\\n        print('downloading', url)\\n        t0 = time.time()\\n        with get(url, timeout=600) as r, open('/content/blender.tar.xz', 'wb') as fh:\\n            while True:\\n                chunk = r.read(1 << 20)\\n                if not chunk: break\\n                fh.write(chunk)\\n        subprocess.run(['tar', '-xf', '/content/blender.tar.xz', '-C', '/content'], check=True)\\n        BLENDER = f'/content/blender-{ver}-linux-x64/blender'\\n        print(f'  {time.time()-t0:.0f}s')\\n    except Exception as e:\\n        print('COULD NOT GET BLENDER:', repr(e))\\n        print('The .glb is already written \u2014 download it from the last cell and stop here.')\\n\\nif BLENDER:\\n    print(subprocess.run([BLENDER, '--version'], capture_output=True, text=True)\\n          .stdout.splitlines()[0])\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 10. Build the .blend\\n\\nTwo acts: the EM sweep from the nearest section to the furthest with the cells popping out as\\nit passes them, then a 240-frame turntable \u2014 10 s of rotation at 24 fps, looping seamlessly.\\nPress Ctrl+F12 in Blender to render the MP4 next to the scene file.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"man = {\\n    'dataset': 'MICrONS minnie65',\\n    'source':  'uJump Filter and show (test set)',\\n    'units':   'um',\\n    'frame':   'microns',   # Y increases downward in every Neuroglancer precomputed source;\\n                            # blend_scene.py maps it to Blender's axes the same way uJump's\\n                            # own .glb export already does\\n    'colors':  COLORS,\\n    'cells': [dict({k: c[k] for k in\\n                    ('type','root_id','nucleus_id','cell_npz','nucleus_npz','position_um')\\n                    if k in c},\\n                   name=f\\\"{c['type'].replace(' ','_')}_{c['root_id']}\\\")\\n              for c in CELLS],\\n}\\nif EM_MANIFEST: man['em'] = EM_MANIFEST\\nif VASC_MESH: man['vasculature'] = VASC_MESH\\njson.dump(man, open('/content/out/manifest.json','w'), indent=1)\\n\\nif not BLENDER:\\n    print('no Blender \u2014 skipping the .blend; the .glb is written and complete')\\nelse:\\n    r = subprocess.run([BLENDER, '--background', '--factory-startup',\\n                        '--python', '/content/blend_scene.py', '--',\\n                        '/content/out/manifest.json',\\n                        '/content/out/microns_cells.blend',\\n                        '/content/out/preview.png'],\\n                       capture_output=True, text=True)\\n    print(r.stdout[-4000:])\\n    if r.returncode: print('STDERR\\\\n', r.stderr[-3000:])\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"# The framing the turntable spends ten seconds in \u2014 worth a look before downloading, and the\\n# one thing a still can settle. The build's own report prints the numbers behind it:\\n#   framing   8/8 bounding-box corners in frame at the turntable, ortho ... um for a ... set\\nfrom IPython.display import Image, display\\nif os.path.exists('/content/out/preview.png'):\\n    display(Image('/content/out/preview.png'))\"}, {\"cell_type\": \"markdown\", \"metadata\": {}, \"source\": \"## 11. Download\\n\\nOpen the `.glb` anywhere; **unzip** the Blender archive and open the `.blend` from inside it \u2014\\nBlender keeps image sequences external and refuses to pack them, so a `.blend` moved away from\\nits `em/` folder opens with every section magenta.\\n\\nThings to check, in order of how likely they are to be wrong:\\n\\n- the viewport is **not empty** on opening (the far clipping plane was the trap);\\n- press play **in camera view** (Numpad 0 \u2014 the zoom is the camera's, so a normal viewport\\n  shows the pan and not the framing): the sections run out with nothing on them, back with the\\n  models in place, then the camera pulls back and turns;\\n- N-panel dimensions read in **micrometres**;\\n- each nucleus is visible **through** its cell, not hidden behind it;\\n- the outliner has one collection per cell type under `Cells`, mirrored under `Nuclei`;\\n- the pia is **up** \u2014 if the column is upside down the axis mapping is wrong, and that is worth\\n  knowing now rather than after this is a button.\"}, {\"cell_type\": \"code\", \"execution_count\": null, \"metadata\": {}, \"outputs\": [], \"source\": \"import shutil\\nfrom google.colab import files\\n\\n# The .glb is one self-contained file, so it goes down as itself.\\nfiles.download('/content/out/microns_cells.glb')\\n\\n# The .blend is NOT self-contained once it has an EM sweep: Blender keeps image sequences\\n# external and refuses to pack them ('packing movies or image sequences not supported'), so\\n# a lone .blend opens with every section magenta. Zip it with its meshes and slices.\\nif os.path.exists('/content/out/microns_cells.blend'):\\n    shutil.make_archive('/content/microns_cells_blender', 'zip', '/content/out')\\n    mb = os.path.getsize('/content/microns_cells_blender.zip') / 1e6\\n    print(f'microns_cells_blender.zip  {mb:.1f} MB  \u2014 unzip, then open microns_cells.blend')\\n    files.download('/content/microns_cells_blender.zip')\"}]}";

  /* Jupyter writes `source` as an array of lines each ending in "\n" except the last; a single
     joined string also works in most readers, but matching the real convention avoids surprises
     in stricter parsers. Same helper, same reason, as core/colabexport.js. */
  function srcLines(s){
    const lines = String(s).split("\n");
    return lines.map((l, i) => i < lines.length - 1 ? l + "\n" : l);
  }

  /* SINGLE-QUOTED where it is safe, because every other line of Python in this notebook is, and
     a params cell that mixes 'type': "23P" reads like it was pasted together by two people. Falls
     back to JSON.stringify -- double quotes, full escaping -- for anything carrying a quote, a
     backslash or a newline; a cell type is free text and could in principle carry any of them.

     The risky characters are built with fromCharCode rather than written as escapes, because this
     file is itself generated and a backslash here has to survive two levels of quoting. It did
     not, once: the character class came out with a real newline in it and the whole module failed
     to parse with "Invalid regular expression: missing /". */
  const PY_RISKY = ["'", String.fromCharCode(92), String.fromCharCode(10), String.fromCharCode(13)];
  function pyStr(s){
    const v = String(s);
    return PY_RISKY.some(ch => v.indexOf(ch) >= 0) ? JSON.stringify(v) : "'" + v + "'";
  }
  function pyBool(v){ return v ? "True" : "False"; }
  function pyNum(n){ return Number.isFinite(n) ? String(n) : "0"; }

  /* gs:// and precomputed:// both reach cloud-volume unchanged; "middleauth+" is a Neuroglancer
     FRONTEND convention its Python reader does not want. Stripped here for the same reason
     core/colabexport.js strips it. */
  function toCloudVolumePath(src){ return String(src||"").replace("middleauth+", ""); }

  /* THE ONE CELL THE PANEL WRITES. Everything it contains is a decision made in the browser:
     which cells matched, what was ticked, where the box is. Everything else in the notebook is
     the pipeline, and arrives verbatim. */
  function paramsCell(opts){
    const inc = opts.include || {};
    const cells = (opts.cells || []).map(c => ({
      type: String(c.type || "Unclassified"),
      root_id: String(c.root_id),
      nucleus_id: c.nucleus_id == null ? null : String(c.nucleus_id)
    }));
    const colors = opts.colors || {};
    const b = opts.boxNM || {};
    /* NANOMETRES IN, MICROMETRES OUT. The panel works in nm because that is what
       core/colabexport.js standardised on; em_plan.py takes dataset micrometres, the same units
       the meshes come back in. One division, in one place, named. */
    const um = v => Number(v) / 1000.0;
    const box = "((" + [um(b.xmin), um(b.ymin), um(b.zmin)].map(pyNum).join(", ") + "), ("
                     + [um(b.xmax), um(b.ymax), um(b.zmax)].map(pyNum).join(", ") + "))";

    const lines = [];
    lines.push("# Written by " + (opts.datasetLabel || opts.datasetId || "the tool")
               + "'s bounding-box panel -- " + (opts.boxLabel || "box") + ".");
    lines.push("# Every other cell in this notebook is the tested pipeline, unchanged.");
    lines.push("");
    lines.push("INCLUDE = {");
    lines.push("    'em':            " + pyBool(inc.em !== false) + ",");
    lines.push("    'segmentation':  " + pyBool(inc.seg !== false) + ",");
    lines.push("    'cell_3d_model': " + pyBool(inc.meshes !== false) + ",");
    lines.push("    'nuclei':        " + pyBool(inc.nuclei !== false) + ",");
    /* Vasculature: Wan & Wei's TriSAM segmentation, cut to this box and surfaced. Defaults ON
       like the rest -- the panel tick is what turns it off -- and the notebook's own cell is
       written so that a failure here (source unreachable, box outside the volume) prints and
       carries on rather than costing the whole run. */
    lines.push("    'vasculature':   " + pyBool(inc.vasc !== false) + ",");
    lines.push("}");
    lines.push("");
    lines.push("CELLS = [");
    cells.forEach(c => {
      lines.push("    {'type': " + pyStr(c.type) + ", 'root_id': " + pyStr(c.root_id)
                 + ", 'nucleus_id': " + (c.nucleus_id ? pyStr(c.nucleus_id) : "None") + "},");
    });
    lines.push("]");
    lines.push("");
    lines.push("# The tool's own palette, per cell type, so a render and the charts agree.");
    lines.push("COLORS = {");
    Object.keys(colors).forEach(k => {
      lines.push("    " + pyStr(k) + ": " + pyStr(colors[k]) + ",");
    });
    lines.push("}");
    lines.push("");
    lines.push("EM  = " + pyStr(toCloudVolumePath(opts.emSource)));
    lines.push("SEG = " + pyStr(toCloudVolumePath(opts.segSource)));
    lines.push("NUC = " + pyStr(toCloudVolumePath(opts.nucSource || "")));
    lines.push("");
    lines.push("# FINEST FIRST. This read [3, 2, 1, 0] with a rule of 'keep the first level");
    lines.push("# under the vertex budget' -- and level 3 is the coarsest, so it always was, and");
    lines.push("# every cell came out at the lowest resolution the dataset has. The fetch cell");
    lines.push("# probes level 3, predicts the finer levels from it, and takes the finest that");
    lines.push("# fits. Raise the budgets for a sharper cell; the download grows with them.");
    lines.push("LOD_PREFERENCE = [0, 1, 2, 3]");
    lines.push("VERTEX_BUDGET       = 2_000_000   # per cell");
    lines.push("VERTEX_BUDGET_TOTAL = 8_000_000   # across the whole export");
    lines.push("");
    lines.push("# ── the box, and what it is allowed to cost ──────────────────────────────────");
    lines.push("EM_MAX_PX       = 1024    # longest in-plane side of a written section");
    lines.push("EM_MAX_SECTIONS = 120     # frames in each sweep");
    lines.push("EM_MAX_MB       = 400     # over the wire, uncompressed uint8");
    lines.push("OVERLAY_OPACITY = 0.35");
    lines.push("");
    lines.push("EM_BOX_MODE    = 'manual'          # the box you drew, not a guess around a cell");
    lines.push("EM_BOX_SIZE_UM = (60.0, 60.0, 30.0)");
    lines.push("EM_BOX_UM      = " + box);
    lines.push("");
    lines.push("on = [k for k, v in INCLUDE.items() if v]");
    /* Plain concatenation rather than an f-string: an f-string with single quotes containing a
       single-quoted subscript only became legal in Python 3.12, and this notebook should not care
       which Python the runtime happens to be. */
    lines.push("print(str(len(CELLS)) + ' cells: ' "
               + "+ ', '.join(sorted(set(c['type'] for c in CELLS))))");
    lines.push("print('including: ' + (', '.join(on) if on else 'NOTHING -- tick something'))");
    return lines.join("\n");
  }

  function buildNotebook(opts){
    const nb = JSON.parse(NB_SOURCE);
    let replaced = 0;
    nb.cells = nb.cells.map(c => {
      if (c.metadata && c.metadata.ujump === "params"){
        replaced++;
        return Object.assign({}, c, {source: srcLines(paramsCell(opts))});
      }
      /* Everything else verbatim, only re-shaped from one string into Jupyter's line array. */
      return Object.assign({}, c, {source: srcLines(c.source)});
    });
    if (replaced !== 1){
      /* Loud rather than silent: a notebook whose parameters were not substituted would run
         against the TEST cells and the test box, and look perfectly plausible doing it. */
      throw new Error("blenderexport: expected 1 params cell, replaced " + replaced);
    }
    nb.metadata = Object.assign({}, nb.metadata, {
      colab: {name: filenameFor(opts), provenance: []}
    });
    return nb;
  }

  function filenameFor(opts){
    return (opts.datasetId || "region") + "_"
      + String(opts.boxLabel || "box").replace(/\s+/g, "_") + "_blender.ipynb";
  }

  function downloadNotebook(opts){
    const nb = buildNotebook(opts);
    const filename = filenameFor(opts);
    const blob = new Blob([JSON.stringify(nb, null, 1)], {type: "application/x-ipynb+json"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return filename;
  }

  return {buildNotebook, downloadNotebook, filenameFor};
})();
